#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DisplayPalette {
    shades: [[u8; 3]; 4],
}

impl DisplayPalette {
    const fn shade_rgb(self, shade: u8) -> [u8; 3] {
        match shade {
            0..=3 => self.shades[shade as usize],
            _ => self.shades[3],
        }
    }
}

