impl PathSelectionDialog {
    fn new() -> Self {
        let (sender, receiver) = mpsc::channel();
        Self {
            pending: false,
            sender,
            receiver,
        }
    }

    fn is_pending(&self) -> bool {
        self.pending
    }

    fn show_file(
        &mut self,
        filters: &[DialogFileFilter<'static>],
        window: &Window,
        default_location: &Path,
    ) -> Result<(), String> {
        if self.pending {
            return Ok(());
        }

        let sender = self.sender.clone();
        map_display_result(
            show_open_file_dialog(
                filters,
                Some(default_location),
                false,
                window,
                Box::new(move |result, _| {
                    let _ = sender.send(map_path_dialog_result(result));
                }),
            ),
            "failed to show SDL3 open file dialog",
        )?;
        self.pending = true;
        Ok(())
    }

    fn show_save_file(
        &mut self,
        filters: &[DialogFileFilter<'static>],
        window: &Window,
        default_location: &Path,
    ) -> Result<(), String> {
        if self.pending {
            return Ok(());
        }

        let sender = self.sender.clone();
        map_display_result(
            show_save_file_dialog(
                filters,
                Some(default_location),
                window,
                Box::new(move |result, _| {
                    let _ = sender.send(map_path_dialog_result(result));
                }),
            ),
            "failed to show SDL3 save file dialog",
        )?;
        self.pending = true;
        Ok(())
    }

    fn show_folder(&mut self, window: &Window, default_location: &Path) {
        if self.pending {
            return;
        }

        let sender = self.sender.clone();
        show_open_folder_dialog(
            Some(default_location),
            false,
            window,
            Box::new(move |result, _| {
                let _ = sender.send(map_path_dialog_result(result));
            }),
        );
        self.pending = true;
    }

    fn take_result(&mut self) -> Option<PathDialogResult> {
        match self.receiver.try_recv() {
            Ok(result) => {
                self.pending = false;
                Some(result)
            }
            Err(TryRecvError::Empty) => None,
            Err(TryRecvError::Disconnected) => {
                self.pending = false;
                None
            }
        }
    }
}

