impl PcWatchRange {
    fn new(start: u16, end: u16) -> Result<Self, String> {
        if end < start {
            return Err(format!(
                "{DESKTOP_PC_WATCH_TRACE_RANGES_ENV_VAR} range end {end:#06X} is below start {start:#06X}"
            ));
        }
        Ok(Self { start, end })
    }

    fn contains(self, pc: u16) -> bool {
        self.start <= pc && pc <= self.end
    }
}

