fn restore_window_after_native_dialog(canvas: &mut Canvas<Window>) {
    let _ = canvas.window_mut().raise();
}

fn apply_machine_settings_change(
    canvas: &mut Canvas<Window>,
    context: &mut FrontendActionContext<'_>,
    title: &str,
    update: impl FnOnce(&mut DesktopConfig),
) -> Result<(), String> {
    let previous_config = context.session.config.clone();
    let mut next_config = previous_config.clone();
    update(&mut next_config);
    if next_config == previous_config {
        return Ok(());
    }

    let effective_config = match rebuild_machine_for_config(canvas, context, &next_config) {
        Ok(effective_config) => effective_config,
        Err(error) => {
            show_warning_message(Some(canvas.window()), title, &error);
            eprintln!("warning: {error}");
            return Ok(());
        }
    };

    context.session.config = effective_config;
    sanitize_external_port_session_for_model(context.session);
    if !context.session.test_runner {
        context
            .settings_store
            .persist_machine_preferences(&context.session.config)?;
    }
    Ok(())
}

fn apply_execution_mode_cycle_change(
    canvas: &mut Canvas<Window>,
    context: &mut FrontendActionContext<'_>,
) -> Result<(), String> {
    let previous_mode = context.session.config.launch.execution_mode;
    let mut candidate_mode = next_execution_mode(previous_mode);
    let mut skipped_errors = Vec::new();

    for _ in 0..2 {
        let mut candidate_config = context.session.config.clone();
        candidate_config.launch.execution_mode = candidate_mode;

        match check_current_session_rebuilds_with_config(context.session, &candidate_config) {
            Ok(()) => {
                for (skipped_mode, error) in skipped_errors {
                    eprintln!(
                        "warning: skipping execution mode {} for current session: {error}",
                        execution_mode_name(skipped_mode)
                    );
                }
                return apply_machine_settings_change(
                    canvas,
                    context,
                    "Execution mode",
                    |config| {
                        config.launch.execution_mode = candidate_mode;
                    },
                );
            }
            Err(error) => {
                skipped_errors.push((candidate_mode, error));
                candidate_mode = next_execution_mode(candidate_mode);
            }
        }
    }

    let message = skipped_errors
        .into_iter()
        .map(|(mode, error)| format!("{}: {error}", execution_mode_name(mode)))
        .collect::<Vec<_>>()
        .join("\n\n");
    let message =
        format!("No alternate execution mode can reload the current session.\n\n{message}");
    show_warning_message(Some(canvas.window()), "Execution mode", &message);
    eprintln!("warning: {message}");
    Ok(())
}

fn check_current_session_rebuilds_with_config(
    session: &DesktopSession,
    config: &DesktopConfig,
) -> Result<(), String> {
    match (
        session.rom_bytes(),
        session.linked_secondary_rom_bytes(),
        session.cgb_infrared_link_active,
        session.pokemon_pikachu_color_active,
        session.pokemon_mystery_gift_active,
        session.external_port_selection,
        session.dmg07_player_count,
    ) {
        (Some(primary_rom_bytes), Some(secondary_rom_bytes), true, _, _, _, _) => {
            load_cgb_infrared_machines_for_roms(
                config,
                &session.current_dir,
                primary_rom_bytes,
                secondary_rom_bytes,
                "checking a CGB IR session",
            )
            .map(|_| ())
        }
        (Some(primary_rom_bytes), _, false, true, _, _, _) => {
            load_machine_for_rom(config, &session.current_dir, primary_rom_bytes).map(|_| ())
        }
        (Some(primary_rom_bytes), _, false, false, true, _, _) => {
            load_machine_for_rom(config, &session.current_dir, primary_rom_bytes).map(|_| ())
        }
        (
            Some(primary_rom_bytes),
            Some(secondary_rom_bytes),
            false,
            false,
            false,
            DesktopExternalPortSelection::GameLink,
            _,
        ) => {
            let primary_loaded =
                load_machine_for_rom(config, &session.current_dir, primary_rom_bytes)?;
            let secondary_loaded =
                load_machine_for_rom(config, &session.current_dir, secondary_rom_bytes)?;
            if primary_loaded.effective_config != secondary_loaded.effective_config {
                return Err(
                    "checking a linked DMG-04 session produced divergent effective configs between the primary and secondary machines"
                        .to_string(),
                );
            }
            Ok(())
        }
        (
            Some(primary_rom_bytes),
            _,
            false,
            false,
            false,
            DesktopExternalPortSelection::FourPlayerAdapter,
            Some(player_count),
        ) => load_dmg07_machines_for_rom(
            config,
            &session.current_dir,
            primary_rom_bytes,
            player_count,
            "checking a DMG-07 session",
        )
        .map(|_| ()),
        (Some(rom_bytes), _, _, _, _, _, _) => {
            load_machine_for_rom(config, &session.current_dir, rom_bytes).map(|_| ())
        }
        (None, _, _, _, _, _, _) => {
            prepare_machine_config(config, &session.current_dir).map(|_| ())
        }
    }
}

fn rebuild_pokemon_mystery_gift_for_config(
    next_config: &DesktopConfig,
    next_session: &DesktopSession,
    primary_rom_bytes: &[u8],
    battery_backed_states: &[Option<PersistentCartState>; PLAYER_SLOT_COUNT],
    mut boot_rom_fallback_warnings: Vec<String>,
) -> Result<RebuildMachineResult, String> {
    let loaded = load_machine_for_rom(next_config, &next_session.current_dir, primary_rom_bytes)?;
    write_cartridge_diagnostics(&loaded.diagnostics);
    if let Some(warning) = loaded.boot_rom_fallback_warning {
        boot_rom_fallback_warnings.push(warning);
    }

    let mut next_machine = DesktopEmulationSession::new_pokemon_mystery_gift(
        loaded.machine,
        next_session.pokemon_mystery_gift_kind,
        next_session.pokemon_mystery_gift_code,
    );
    restore_battery_backed_states_by_player_slot(
        &mut next_machine,
        battery_backed_states,
        "after reconfigure",
    )?;
    apply_session_pocket_camera_frame_to_desktop_session(next_session, &mut next_machine)?;

    let effective_config = loaded.effective_config;
    let next_save_sessions = open_save_sessions_for_session(
        &DesktopSession {
            config: effective_config.clone(),
            linked_secondary_rom: None,
            external_port_selection: DesktopExternalPortSelection::None,
            dmg07_player_count: None,
            cgb_infrared_link_active: false,
            pokemon_pikachu_color_active: false,
            pokemon_mystery_gift_active: true,
            ..next_session.clone()
        },
        &mut next_machine,
    )?;
    Ok((
        effective_config,
        boot_rom_fallback_warnings,
        next_machine,
        next_save_sessions,
    ))
}

fn rebuild_machine_for_config(
    canvas: &mut Canvas<Window>,
    context: &mut FrontendActionContext<'_>,
    next_config: &DesktopConfig,
) -> Result<DesktopConfig, String> {
    drain_printed_pages_into_printer_output(
        canvas.window(),
        context.session,
        context.runtime,
        context.machine,
    );
    flush_pending_printer_output(canvas.window(), context.session, context.runtime);
    context.runtime.rtc_sync.apply_to_machine(context.machine);

    let battery_backed_states = battery_backed_states_by_player_slot(context.machine);

    let mut previous_save_sessions =
        std::mem::replace(&mut context.runtime.save_sessions, empty_save_sessions());
    for slot in PlayerSlot::ALL {
        if let Some(save_session) = previous_save_sessions[slot.index()].as_mut()
            && let Some(slot_machine) = context.machine.machine_for_player_slot(slot)
            && let Err(error) = save_session.close(slot_machine)
        {
            context.runtime.save_sessions = previous_save_sessions;
            return Err(error);
        }
    }

    let rebuild_result: Result<RebuildMachineResult, String> = (|| {
        let mut boot_rom_fallback_warnings = Vec::new();

        let next_external_port_selection = supported_external_port_selection_for_model(
            next_config.launch.console_model,
            context.session.external_port_selection,
        );
        let next_linked_secondary_rom = if context.session.cgb_infrared_link_active
            || next_external_port_selection == DesktopExternalPortSelection::GameLink
        {
            context.session.linked_secondary_rom.clone()
        } else {
            None
        };
        let next_dmg07_player_count =
            if next_external_port_selection == DesktopExternalPortSelection::FourPlayerAdapter {
                context.session.dmg07_player_count
            } else {
                None
            };

        let next_session = DesktopSession {
            config: next_config.clone(),
            test_runner: context.session.test_runner,
            benchmark: context.session.benchmark.clone(),
            current_dir: context.session.current_dir.clone(),
            loaded_rom: context.session.loaded_rom.clone(),
            linked_secondary_rom: next_linked_secondary_rom,
            dmg07_player_count: next_dmg07_player_count,
            cgb_infrared_link_active: context.session.cgb_infrared_link_active,
            pokemon_pikachu_color_active: context.session.pokemon_pikachu_color_active,
            pokemon_pikachu_color_gift: context.session.pokemon_pikachu_color_gift,
            pokemon_mystery_gift_active: context.session.pokemon_mystery_gift_active,
            pokemon_mystery_gift_kind: context.session.pokemon_mystery_gift_kind,
            pokemon_mystery_gift_code: context.session.pokemon_mystery_gift_code,
            last_open_directory: context.session.last_open_directory.clone(),
            recent_roms: context.session.recent_roms.clone(),
            pocket_camera_frame: context.session.pocket_camera_frame.clone(),
            external_port_selection: next_external_port_selection,
        };

        match (
            next_session.rom_bytes(),
            next_session.linked_secondary_rom_bytes(),
            next_session.cgb_infrared_link_active,
            next_session.pokemon_pikachu_color_active,
            next_session.pokemon_mystery_gift_active,
            next_session.external_port_selection,
            next_session.dmg07_player_count,
        ) {
            (Some(primary_rom_bytes), Some(secondary_rom_bytes), true, _, _, _, _) => {
                let loaded = load_cgb_infrared_machines_for_roms(
                    next_config,
                    &context.session.current_dir,
                    primary_rom_bytes,
                    secondary_rom_bytes,
                    "reconfiguring a CGB IR session",
                )?;
                write_cartridge_diagnostics(&loaded.diagnostics);
                boot_rom_fallback_warnings.extend(loaded.boot_rom_fallback_warnings);
                let mut next_machine = loaded.machine;
                restore_battery_backed_states_by_player_slot(
                    &mut next_machine,
                    &battery_backed_states,
                    "after reconfigure",
                )?;
                apply_session_pocket_camera_frame_to_desktop_session(
                    &next_session,
                    &mut next_machine,
                )?;

                let effective_config = loaded.effective_config;
                let next_save_sessions = open_save_sessions_for_session(
                    &DesktopSession {
                        config: effective_config.clone(),
                        external_port_selection: DesktopExternalPortSelection::None,
                        dmg07_player_count: None,
                        cgb_infrared_link_active: true,
                        pokemon_pikachu_color_active: false,
                        pokemon_mystery_gift_active: false,
                        ..next_session
                    },
                    &mut next_machine,
                )?;
                Ok((
                    effective_config,
                    boot_rom_fallback_warnings,
                    next_machine,
                    next_save_sessions,
                ))
            }
            (Some(primary_rom_bytes), _, false, true, _, _, _) => {
                let loaded = load_machine_for_rom(
                    next_config,
                    &context.session.current_dir,
                    primary_rom_bytes,
                )?;
                write_cartridge_diagnostics(&loaded.diagnostics);
                if let Some(warning) = loaded.boot_rom_fallback_warning {
                    boot_rom_fallback_warnings.push(warning);
                }

                let mut next_machine = DesktopEmulationSession::new_pokemon_pikachu_color(
                    loaded.machine,
                    next_session.pokemon_pikachu_color_gift,
                    PokemonPikachuColorRegion::Auto,
                );
                restore_battery_backed_states_by_player_slot(
                    &mut next_machine,
                    &battery_backed_states,
                    "after reconfigure",
                )?;
                apply_session_pocket_camera_frame_to_desktop_session(
                    &next_session,
                    &mut next_machine,
                )?;

                let effective_config = loaded.effective_config;
                let next_save_sessions = open_save_sessions_for_session(
                    &DesktopSession {
                        config: effective_config.clone(),
                        linked_secondary_rom: None,
                        external_port_selection: DesktopExternalPortSelection::None,
                        dmg07_player_count: None,
                        cgb_infrared_link_active: false,
                        pokemon_pikachu_color_active: true,
                        pokemon_mystery_gift_active: false,
                        ..next_session
                    },
                    &mut next_machine,
                )?;
                Ok((
                    effective_config,
                    boot_rom_fallback_warnings,
                    next_machine,
                    next_save_sessions,
                ))
            }
            (Some(primary_rom_bytes), _, false, false, true, _, _) => {
                rebuild_pokemon_mystery_gift_for_config(
                    next_config,
                    &next_session,
                    primary_rom_bytes,
                    &battery_backed_states,
                    boot_rom_fallback_warnings,
                )
            }
            (
                Some(primary_rom_bytes),
                Some(secondary_rom_bytes),
                false,
                false,
                false,
                DesktopExternalPortSelection::GameLink,
                _,
            ) => {
                let primary_loaded = load_machine_for_rom(
                    next_config,
                    &context.session.current_dir,
                    primary_rom_bytes,
                )?;
                let secondary_loaded = load_machine_for_rom(
                    next_config,
                    &context.session.current_dir,
                    secondary_rom_bytes,
                )?;
                if primary_loaded.effective_config != secondary_loaded.effective_config {
                    return Err(
                        "reconfiguring a linked DMG-04 session produced divergent effective configs between primary and secondary machines"
                            .to_string(),
                    );
                }

                write_cartridge_diagnostics(&primary_loaded.diagnostics);
                write_cartridge_diagnostics(&secondary_loaded.diagnostics);
                if let Some(warning) = primary_loaded.boot_rom_fallback_warning {
                    boot_rom_fallback_warnings.push(warning);
                }
                if let Some(warning) = secondary_loaded.boot_rom_fallback_warning {
                    boot_rom_fallback_warnings.push(warning);
                }

                let mut next_machine = DesktopEmulationSession::new_single(primary_loaded.machine);
                next_machine.attach_secondary_dmg04(secondary_loaded.machine)?;
                restore_battery_backed_states_by_player_slot(
                    &mut next_machine,
                    &battery_backed_states,
                    "after reconfigure",
                )?;
                apply_session_pocket_camera_frame_to_desktop_session(
                    &next_session,
                    &mut next_machine,
                )?;

                let effective_config = primary_loaded.effective_config;
                let next_save_sessions = open_save_sessions_for_session(
                    &DesktopSession {
                        config: effective_config.clone(),
                        cgb_infrared_link_active: false,
                        pokemon_pikachu_color_active: false,
                        pokemon_mystery_gift_active: false,
                        ..next_session
                    },
                    &mut next_machine,
                )?;
                Ok((
                    effective_config,
                    boot_rom_fallback_warnings,
                    next_machine,
                    next_save_sessions,
                ))
            }
            (
                Some(primary_rom_bytes),
                _,
                false,
                false,
                false,
                DesktopExternalPortSelection::FourPlayerAdapter,
                Some(player_count),
            ) => {
                let loaded = load_dmg07_machines_for_rom(
                    next_config,
                    &context.session.current_dir,
                    primary_rom_bytes,
                    player_count,
                    "reconfiguring a DMG-07 session",
                )?;
                write_cartridge_diagnostics(&loaded.diagnostics);
                boot_rom_fallback_warnings.extend(loaded.boot_rom_fallback_warnings);
                let mut next_machine = loaded.machine;
                restore_battery_backed_states_by_player_slot(
                    &mut next_machine,
                    &battery_backed_states,
                    "after reconfigure",
                )?;
                apply_session_pocket_camera_frame_to_desktop_session(
                    &next_session,
                    &mut next_machine,
                )?;

                let effective_config = loaded.effective_config;
                let next_save_sessions = open_save_sessions_for_session(
                    &DesktopSession {
                        config: effective_config.clone(),
                        linked_secondary_rom: None,
                        external_port_selection: DesktopExternalPortSelection::FourPlayerAdapter,
                        dmg07_player_count: Some(player_count),
                        cgb_infrared_link_active: false,
                        pokemon_pikachu_color_active: false,
                        pokemon_mystery_gift_active: false,
                        ..next_session
                    },
                    &mut next_machine,
                )?;
                Ok((
                    effective_config,
                    boot_rom_fallback_warnings,
                    next_machine,
                    next_save_sessions,
                ))
            }
            (Some(rom_bytes), _, _, _, _, _, _) => {
                let loaded =
                    load_machine_for_rom(next_config, &context.session.current_dir, rom_bytes)?;
                write_cartridge_diagnostics(&loaded.diagnostics);
                if let Some(warning) = loaded.boot_rom_fallback_warning {
                    boot_rom_fallback_warnings.push(warning);
                }
                let mut next_machine = DesktopEmulationSession::new_single(loaded.machine);
                apply_external_port_selection_to_machine(
                    next_machine.primary_machine_mut(),
                    next_session.external_port_selection,
                );
                restore_battery_backed_states_by_player_slot(
                    &mut next_machine,
                    &battery_backed_states,
                    "after reconfigure",
                )?;
                apply_session_pocket_camera_frame_to_desktop_session(
                    &next_session,
                    &mut next_machine,
                )?;

                let effective_config = loaded.effective_config;
                let next_save_sessions = open_save_sessions_for_session(
                    &DesktopSession {
                        config: effective_config.clone(),
                        linked_secondary_rom: None,
                        dmg07_player_count: None,
                        cgb_infrared_link_active: false,
                        pokemon_pikachu_color_active: false,
                        pokemon_mystery_gift_active: false,
                        external_port_selection: next_session.external_port_selection,
                        ..next_session
                    },
                    &mut next_machine,
                )?;
                Ok((
                    effective_config,
                    boot_rom_fallback_warnings,
                    next_machine,
                    next_save_sessions,
                ))
            }
            (None, _, _, _, _, _, _) => {
                let prepared = prepare_machine_config(next_config, &context.session.current_dir)?;
                if let Some(warning) = prepared.boot_rom_fallback_warning {
                    boot_rom_fallback_warnings.push(warning);
                }

                let mut next_machine = DesktopEmulationSession::new_single(Machine::new_summary(
                    prepared.machine_config,
                ));
                apply_external_port_selection_to_machine(
                    next_machine.primary_machine_mut(),
                    next_session.external_port_selection,
                );
                Ok((
                    prepared.effective_config,
                    boot_rom_fallback_warnings,
                    next_machine,
                    empty_save_sessions(),
                ))
            }
        }
    })();

    let (effective_config, boot_rom_fallback_warnings, next_machine, next_save_sessions) =
        match rebuild_result {
            Ok(value) => value,
            Err(error) => {
                context.runtime.save_sessions = previous_save_sessions;
                return Err(error);
            }
        };

    if let Some(audio_output) = &mut context.runtime.audio_output {
        audio_output.clear_buffer()?;
    }

    for warning in &boot_rom_fallback_warnings {
        log_boot_rom_fallback_warning(Some(warning));
    }
    clear_live_input_state(context.machine, context.runtime);
    *context.machine = next_machine;
    reset_frontend_timeline_state(context.runtime);
    context.runtime.save_sessions = next_save_sessions;
    context.runtime.rtc_sync.resync_to_host_clock();
    context.performance_counter.reset_base_title(
        canvas.window_mut(),
        window_title(context.session, &effective_config),
    )?;
    Ok(effective_config)
}

fn boot_rom_dialog_default_location(session: &DesktopSession) -> PathBuf {
    let configured_source = session
        .config
        .boot_rom
        .search_path
        .as_deref()
        .map(|path| resolve_path(&session.current_dir, path));
    match configured_source {
        Some(path) if path.is_dir() => path,
        Some(path) => path
            .parent()
            .unwrap_or(session.current_dir.as_path())
            .to_path_buf(),
        None => env::var_os(BOOT_ROM_ROOT_ENV_VAR)
            .map(PathBuf::from)
            .map(|path| {
                if path.is_dir() {
                    path
                } else {
                    path.parent()
                        .unwrap_or(session.current_dir.as_path())
                        .to_path_buf()
                }
            })
            .unwrap_or_else(|| session.current_dir.clone()),
    }
}

fn save_directory_dialog_default_location(session: &DesktopSession) -> PathBuf {
    match &session.config.saves.directory_policy {
        SaveDirectoryPolicy::Custom(path) => {
            let path = resolve_path(&session.current_dir, path);
            if path.is_dir() {
                path
            } else {
                path.parent()
                    .unwrap_or(session.current_dir.as_path())
                    .to_path_buf()
            }
        }
        SaveDirectoryPolicy::RomFolderSavesSubdir => session.rom_directory_hint().to_path_buf(),
    }
}

fn external_save_export_dialog_default_location(session: &DesktopSession) -> PathBuf {
    external_save_dialog_default_location(session, "export")
}

fn external_save_import_dialog_default_location(session: &DesktopSession) -> PathBuf {
    external_save_dialog_default_location(session, "import")
}

fn external_save_dialog_default_location(session: &DesktopSession, subdirectory: &str) -> PathBuf {
    if let Some(rom_path) = session.rom_path() {
        return resolve_path(
            &session.current_dir,
            &session.config.saves.directory_policy.resolve(rom_path),
        )
        .join(subdirectory)
        .join(external_save_default_file_name(session));
    }

    session
        .current_dir
        .join("saves")
        .join(subdirectory)
        .join(external_save_default_file_name(session))
}

fn external_save_default_file_name(session: &DesktopSession) -> String {
    let stem = session
        .rom_path()
        .and_then(|rom_path| {
            session
                .config
                .saves
                .resolve_key(rom_path)
                .ok()
                .flatten()
                .map(|key| key.as_str().to_string())
                .or_else(|| {
                    rom_path
                        .file_stem()
                        .map(|stem| stem.to_string_lossy().into_owned())
                })
        })
        .filter(|stem| !stem.is_empty())
        .unwrap_or_else(|| "save".to_string());
    format!("{stem}.{EXTERNAL_SAVE_FILE_EXTENSION}")
}

fn resolve_selected_external_save_path(
    session: &DesktopSession,
    selected_path: PathBuf,
) -> PathBuf {
    if selected_path.is_absolute() {
        selected_path
    } else {
        resolve_path(&session.current_dir, &selected_path)
    }
}

fn resolve_external_save_export_path(session: &DesktopSession, selected_path: PathBuf) -> PathBuf {
    let mut path = resolve_selected_external_save_path(session, selected_path);
    if path.extension().is_none() {
        path.set_extension(EXTERNAL_SAVE_FILE_EXTENSION);
    }
    path
}

fn resolve_external_save_import_path(session: &DesktopSession, selected_path: PathBuf) -> PathBuf {
    resolve_selected_external_save_path(session, selected_path)
}

fn primary_save_root_and_key(
    session: &DesktopSession,
) -> Result<Option<(PathBuf, CartridgeSaveKey)>, String> {
    let Some(rom_path) = session.rom_path() else {
        return Ok(None);
    };
    let Some(save_root) = session.config.saves.resolve_directory(rom_path) else {
        return Ok(None);
    };
    let save_key = session
        .config
        .saves
        .resolve_key(rom_path)
        .map_err(|error| error.to_string())?;
    Ok(save_key.map(|key| (resolve_path(&session.current_dir, &save_root), key)))
}

fn export_current_external_save(
    selected_path: PathBuf,
    context: &mut FrontendActionContext<'_>,
) -> Result<PathBuf, String> {
    context.runtime.rtc_sync.apply_to_machine(context.machine);
    let cartridge = context.machine.primary_machine().cartridge();
    let metadata = cartridge.persistence_metadata();
    if !uses_battery_backed_hardware_persistence(metadata) {
        return Err(
            "current game does not expose battery-backed persistence to export".to_string(),
        );
    }

    let export_path = resolve_external_save_export_path(context.session, selected_path);
    let current_unix_seconds = SystemCartridgeSaveTimeSource.now_unix_seconds();
    let external_bytes = encode_external_cartridge_save(
        metadata,
        &cartridge.persistent_state(),
        current_unix_seconds,
        ExternalSaveExportFormat::default(),
    )
    .map_err(|error| format_external_save_error("export", error))?;

    if let Some(parent) = export_path.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent).map_err(|error| {
            format_path_error(
                "failed to create external save export directory",
                parent,
                &error.to_string(),
            )
        })?;
    }
    fs::write(&export_path, external_bytes).map_err(|error| {
        format_path_error(
            "failed to write external save",
            &export_path,
            &error.to_string(),
        )
    })?;
    Ok(export_path)
}

fn import_external_save_for_current_rom(
    selected_path: PathBuf,
    context: &mut FrontendActionContext<'_>,
) -> Result<PathBuf, String> {
    let import_path = resolve_external_save_import_path(context.session, selected_path);
    let (save_root, save_key) = primary_save_root_and_key(context.session)?.ok_or_else(|| {
        "save support is disabled or no current ROM save key could be resolved".to_string()
    })?;
    let external_bytes = fs::read(&import_path).map_err(|error| {
        format_path_error(
            "failed to read external save",
            &import_path,
            &error.to_string(),
        )
    })?;

    let cartridge = context.machine.primary_machine().cartridge();
    let metadata = cartridge.persistence_metadata();
    if !uses_battery_backed_hardware_persistence(metadata) {
        return Err(
            "current game does not expose battery-backed persistence to import".to_string(),
        );
    }

    let import_unix_seconds = SystemCartridgeSaveTimeSource.now_unix_seconds();
    let imported_state = import_external_cartridge_save(
        metadata,
        &cartridge.persistent_state(),
        &external_bytes,
        import_unix_seconds,
    )
    .map_err(|error| format_external_save_error("import", error))?;

    let mut validation_cartridge = cartridge.clone();
    validation_cartridge
        .restore_persistent_state(&imported_state)
        .map_err(|error| {
            format_debug_error(
                "imported external save does not match the current cartridge",
                &format!("{error:?}"),
            )
        })?;

    let mut previous_primary_save_session =
        context.runtime.save_sessions[PlayerSlot::P1.index()].take();
    if let Some(save_session) = previous_primary_save_session.as_mut()
        && let Err(error) = save_session.close(context.machine.primary_machine())
    {
        context.runtime.save_sessions[PlayerSlot::P1.index()] = previous_primary_save_session;
        return Err(error);
    }

    let mut store = FilesystemCartridgeSaveStore::with_time_source(
        save_root,
        FixedCartridgeSaveTimeSource::new(import_unix_seconds),
    );
    let save_path = store.preferred_path_for_state(&save_key, metadata, &imported_state);
    let save_result = store.save(&save_key, metadata, &imported_state);
    match save_result {
        Ok(write) => {
            context.runtime.save_sessions[PlayerSlot::P1.index()] = None;
            Ok(write.path)
        }
        Err(error) => {
            context.runtime.save_sessions[PlayerSlot::P1.index()] = previous_primary_save_session;
            Err(format_path_error(
                "failed to write imported save",
                &save_path,
                &error.to_string(),
            ))
        }
    }
}

fn format_external_save_error(action: &str, error: ExternalSaveError) -> String {
    format!("failed to {action} external save: {error}")
}

fn load_selected_camera_image(
    selected_path: PathBuf,
    session: &DesktopSession,
) -> Result<PocketCameraFrame, String> {
    let image_path = if selected_path.is_absolute() {
        selected_path
    } else {
        resolve_path(&session.current_dir, &selected_path)
    };
    let file = fs::File::open(&image_path).map_err(|error| {
        format_path_error(
            "failed to read Pocket Camera image",
            &image_path,
            &error.to_string(),
        )
    })?;

    let mut decoder = Decoder::new(BufReader::new(file));
    decoder.set_transformations(Transformations::EXPAND | Transformations::STRIP_16);
    let mut reader = decoder.read_info().map_err(|error| {
        format_path_error(
            "failed to decode PNG metadata",
            &image_path,
            &error.to_string(),
        )
    })?;
    let output_buffer_size = reader.output_buffer_size().ok_or_else(|| {
        format_path_error(
            "failed to decode PNG metadata",
            &image_path,
            "decoded PNG output buffer is too large",
        )
    })?;
    let mut buffer = vec![0; output_buffer_size];
    let info = reader.next_frame(&mut buffer).map_err(|error| {
        format_path_error(
            "failed to decode PNG image",
            &image_path,
            &error.to_string(),
        )
    })?;
    let width = u16::try_from(info.width).map_err(|_| {
        format_path_error(
            "PNG width exceeds Pocket Camera limits",
            &image_path,
            &info.width.to_string(),
        )
    })?;
    let height = u16::try_from(info.height).map_err(|_| {
        format_path_error(
            "PNG height exceeds Pocket Camera limits",
            &image_path,
            &info.height.to_string(),
        )
    })?;
    let frame_bytes = &buffer[..info.buffer_size()];

    let grayscale_pixels = match info.color_type {
        ColorType::Grayscale => frame_bytes.to_vec(),
        ColorType::GrayscaleAlpha => frame_bytes.chunks_exact(2).map(|chunk| chunk[0]).collect(),
        ColorType::Rgb => frame_bytes
            .chunks_exact(3)
            .map(|chunk| grayscale_from_rgb(chunk[0], chunk[1], chunk[2]))
            .collect(),
        ColorType::Rgba => frame_bytes
            .chunks_exact(4)
            .map(|chunk| grayscale_from_rgb(chunk[0], chunk[1], chunk[2]))
            .collect(),
        ColorType::Indexed => {
            return Err(format_path_error(
                "unsupported indexed PNG after expansion",
                &image_path,
                "decoder left the image indexed",
            ));
        }
    };

    Ok(PocketCameraFrame {
        width,
        height,
        grayscale_pixels,
    })
}

fn grayscale_from_rgb(red: u8, green: u8, blue: u8) -> u8 {
    ((299_u32 * u32::from(red) + 587_u32 * u32::from(green) + 114_u32 * u32::from(blue) + 500)
        / 1000) as u8
}

fn load_selected_rom(
    selected_path: PathBuf,
    session: &DesktopSession,
) -> Result<LoadedRom, String> {
    let rom_path = if selected_path.is_absolute() {
        selected_path
    } else {
        resolve_path(&session.current_dir, &selected_path)
    };
    let rom_bytes = match fs::read(&rom_path) {
        Ok(rom_bytes) => rom_bytes,
        Err(error) => {
            return Err(format_path_error(
                "failed to read ROM",
                &rom_path,
                &error.to_string(),
            ));
        }
    };

    Ok(LoadedRom {
        path: rom_path,
        bytes: rom_bytes,
    })
}

fn next_single_external_port_selection(
    current_selection: DesktopExternalPortSelection,
) -> DesktopExternalPortSelection {
    match current_selection {
        DesktopExternalPortSelection::None | DesktopExternalPortSelection::Printer => {
            current_selection
        }
        DesktopExternalPortSelection::GameLink
        | DesktopExternalPortSelection::FourPlayerAdapter => DesktopExternalPortSelection::None,
    }
}

fn open_selected_rom(
    event_pump: &sdl3::EventPump,
    canvas: &mut Canvas<Window>,
    selected_path: PathBuf,
    context: &mut FrontendActionContext<'_>,
) -> Result<(), String> {
    drain_printed_pages_into_printer_output(
        canvas.window(),
        context.session,
        context.runtime,
        context.machine,
    );
    flush_pending_printer_output(canvas.window(), context.session, context.runtime);
    context.runtime.rtc_sync.apply_to_machine(context.machine);

    let next_loaded_rom = load_selected_rom(selected_path, context.session)?;
    let loaded = load_machine_for_rom(
        &context.session.config,
        &context.session.current_dir,
        &next_loaded_rom.bytes,
    )?;
    log_boot_rom_fallback_warning(loaded.boot_rom_fallback_warning.as_deref());
    write_cartridge_diagnostics(&loaded.diagnostics);
    let effective_config = loaded.effective_config;
    let config_fell_back = effective_config != context.session.config;
    let mut next_machine = DesktopEmulationSession::new_single(loaded.machine);
    let next_external_port_selection = supported_external_port_selection_for_model(
        effective_config.launch.console_model,
        next_single_external_port_selection(context.session.external_port_selection),
    );
    apply_external_port_selection_to_machine(
        next_machine.primary_machine_mut(),
        next_external_port_selection,
    );
    let next_session = DesktopSession {
        config: effective_config.clone(),
        test_runner: context.session.test_runner,
        benchmark: context.session.benchmark.clone(),
        current_dir: context.session.current_dir.clone(),
        loaded_rom: Some(next_loaded_rom),
        linked_secondary_rom: None,
        dmg07_player_count: None,
        cgb_infrared_link_active: false,
        pokemon_pikachu_color_active: false,
        pokemon_pikachu_color_gift: context.session.pokemon_pikachu_color_gift,
        pokemon_mystery_gift_active: false,
        pokemon_mystery_gift_kind: context.session.pokemon_mystery_gift_kind,
        pokemon_mystery_gift_code: context.session.pokemon_mystery_gift_code,
        last_open_directory: context.session.last_open_directory.clone(),
        recent_roms: context.session.recent_roms.clone(),
        pocket_camera_frame: context.session.pocket_camera_frame.clone(),
        external_port_selection: next_external_port_selection,
    };
    apply_session_pocket_camera_frame_to_desktop_session(&next_session, &mut next_machine)?;
    let next_save_sessions = open_save_sessions_for_session(&next_session, &mut next_machine)?;

    close_runtime_save_sessions(context.runtime, context.machine)?;
    let next_console_model = next_machine.primary_machine().apu().console_model();

    context.session.config = effective_config;
    context.session.loaded_rom = next_session.loaded_rom;
    context.session.linked_secondary_rom = None;
    context.session.dmg07_player_count = None;
    context.session.cgb_infrared_link_active = false;
    context.session.pokemon_pikachu_color_active = false;
    context.session.pokemon_mystery_gift_active = false;
    context.session.last_open_directory = context
        .session
        .loaded_rom
        .as_ref()
        .and_then(|rom| rom.path.parent().map(Path::to_path_buf));
    context.session.external_port_selection = next_external_port_selection;
    if config_fell_back && !context.session.test_runner {
        context
            .settings_store
            .persist_machine_preferences(&context.session.config)?;
    }
    if !context.session.test_runner
        && let Some(rom_path) = context.session.rom_path()
    {
        context.settings_store.remember_loaded_rom(rom_path)?;
        context.session.recent_roms = context.settings_store.recent_roms().to_vec();
    }
    clear_live_input_state(context.machine, context.runtime);
    *context.machine = next_machine;
    reset_frontend_timeline_state(context.runtime);
    if let Some(audio_output) = &mut context.runtime.audio_output {
        audio_output.reset_for_session_swap(next_console_model)?;
    }
    match context.runtime.audio_recording_mode {
        DesktopAudioRecordingMode::Disabled => {
            finish_audio_recorder(&mut context.runtime.audio_recorder)?;
        }
        DesktopAudioRecordingMode::Automatic => {
            restart_automatic_audio_recorder(context.runtime, context.session, context.machine)?;
        }
        DesktopAudioRecordingMode::Explicit(_) => {
            if let Some(audio_recorder) = &mut context.runtime.audio_recorder {
                audio_recorder.reset_for_session_swap(next_console_model)?;
            }
        }
    }
    context.runtime.save_sessions = next_save_sessions;
    context.runtime.rtc_sync.resync_to_host_clock();
    match autoload_machine_state_slot_if_available(
        context.session,
        context.machine,
        context.runtime,
        context.frame_pacer,
    ) {
        Ok(Some(path)) => {
            eprintln!("info: autoloaded state from {}", path.display());
        }
        Ok(None) => {}
        Err(error) => {
            show_warning_message(Some(canvas.window()), "Autoload State", &error);
            eprintln!("warning: {error}");
        }
    }
    context.performance_counter.reset_base_title(
        canvas.window_mut(),
        window_title(context.session, &context.session.config),
    )?;
    context.runtime.paused = false;

    if context.runtime.menu_state.is_open() {
        close_menu(event_pump, context.machine, context.runtime)?;
    }

    Ok(())
}

fn open_selected_linked_secondary_rom(
    event_pump: &sdl3::EventPump,
    canvas: &mut Canvas<Window>,
    selected_path: PathBuf,
    context: &mut FrontendActionContext<'_>,
) -> Result<(), String> {
    if !context.session.has_loaded_rom() {
        return Err(
            "GAME LINK requires a primary ROM before selecting a second cartridge".to_string(),
        );
    }
    if !context
        .session
        .config
        .launch
        .console_model
        .allows_ext_port_menu()
    {
        return Ok(());
    }

    let next_secondary_rom = load_selected_rom(selected_path, context.session)?;
    activate_game_link_with_secondary_rom(event_pump, canvas, next_secondary_rom, context)
}

fn open_game_link_secondary_rom_dialog(
    canvas: &mut Canvas<Window>,
    context: &mut FrontendActionContext<'_>,
) {
    if !context.session.has_loaded_rom()
        || !context
            .session
            .config
            .launch
            .console_model
            .allows_ext_port_menu()
    {
        return;
    }

    context.runtime.open_rom_dialog_mode = OpenRomDialogMode::LinkedSecondary;
    let default_location = context.session.rom_directory_hint();
    if let Err(error) = context.runtime.open_rom_dialog.show_file(
        &ROM_FILE_DIALOG_FILTERS,
        canvas.window(),
        default_location,
    ) {
        context.runtime.open_rom_dialog_mode = OpenRomDialogMode::Primary;
        show_warning_message(Some(canvas.window()), "GAME LINK", &error);
        eprintln!("warning: {error}");
    }
}

fn activate_game_link_with_secondary_rom(
    event_pump: &sdl3::EventPump,
    canvas: &mut Canvas<Window>,
    next_secondary_rom: LoadedRom,
    context: &mut FrontendActionContext<'_>,
) -> Result<(), String> {
    if !context.session.has_loaded_rom() {
        return Err(
            "GAME LINK requires a primary ROM before selecting a second cartridge".to_string(),
        );
    }
    if !context
        .session
        .config
        .launch
        .console_model
        .allows_ext_port_menu()
    {
        return Ok(());
    }

    drain_printed_pages_into_printer_output(
        canvas.window(),
        context.session,
        context.runtime,
        context.machine,
    );
    flush_pending_printer_output(canvas.window(), context.session, context.runtime);
    context.runtime.rtc_sync.apply_to_machine(context.machine);

    let Some(primary_rom_bytes) = context.session.rom_bytes() else {
        return Err(
            "GAME LINK requires a primary ROM before selecting a second cartridge".to_string(),
        );
    };
    let primary_battery_backed_state = uses_battery_backed_hardware_persistence(
        context
            .machine
            .primary_machine()
            .cartridge()
            .persistence_metadata(),
    )
    .then(|| {
        context
            .machine
            .primary_machine()
            .cartridge()
            .persistent_state()
    });

    let loaded_primary = load_machine_for_rom(
        &context.session.config,
        &context.session.current_dir,
        primary_rom_bytes,
    )?;
    let loaded_secondary = load_machine_for_rom(
        &context.session.config,
        &context.session.current_dir,
        &next_secondary_rom.bytes,
    )?;
    if loaded_primary.effective_config != loaded_secondary.effective_config {
        return Err(
            "activating GAME LINK produced divergent effective configs between primary and secondary machines"
                .to_string(),
        );
    }

    log_boot_rom_fallback_warning(loaded_primary.boot_rom_fallback_warning.as_deref());
    write_cartridge_diagnostics(&loaded_primary.diagnostics);
    log_boot_rom_fallback_warning(loaded_secondary.boot_rom_fallback_warning.as_deref());
    write_cartridge_diagnostics(&loaded_secondary.diagnostics);

    let effective_config = loaded_primary.effective_config;
    let config_fell_back = effective_config != context.session.config;
    let mut next_machine = DesktopEmulationSession::new_single(loaded_primary.machine);
    if let Some(persistent_state) = primary_battery_backed_state
        && let Err(error) = next_machine
            .primary_machine_mut()
            .restore_cartridge_persistent_state(&persistent_state)
    {
        return Err(format!(
            "failed to restore battery-backed persistence while activating GAME LINK: {error:?}"
        ));
    }
    next_machine.attach_secondary_dmg04(loaded_secondary.machine)?;

    let next_session = DesktopSession {
        config: effective_config.clone(),
        test_runner: context.session.test_runner,
        benchmark: context.session.benchmark.clone(),
        current_dir: context.session.current_dir.clone(),
        loaded_rom: context.session.loaded_rom.clone(),
        linked_secondary_rom: Some(next_secondary_rom),
        dmg07_player_count: None,
        cgb_infrared_link_active: false,
        pokemon_pikachu_color_active: false,
        pokemon_pikachu_color_gift: context.session.pokemon_pikachu_color_gift,
        pokemon_mystery_gift_active: false,
        pokemon_mystery_gift_kind: context.session.pokemon_mystery_gift_kind,
        pokemon_mystery_gift_code: context.session.pokemon_mystery_gift_code,
        last_open_directory: context.session.last_open_directory.clone(),
        recent_roms: context.session.recent_roms.clone(),
        pocket_camera_frame: context.session.pocket_camera_frame.clone(),
        external_port_selection: DesktopExternalPortSelection::GameLink,
    };
    apply_session_pocket_camera_frame_to_desktop_session(&next_session, &mut next_machine)?;
    let next_save_sessions = open_save_sessions_for_session(&next_session, &mut next_machine)?;

    close_runtime_save_sessions(context.runtime, context.machine)?;
    let next_console_model = next_machine.primary_machine().apu().console_model();

    context.session.config = effective_config;
    context.session.linked_secondary_rom = next_session.linked_secondary_rom;
    context.session.dmg07_player_count = None;
    context.session.cgb_infrared_link_active = false;
    context.session.pokemon_pikachu_color_active = false;
    context.session.pokemon_mystery_gift_active = false;
    context.session.last_open_directory = context
        .session
        .linked_secondary_rom
        .as_ref()
        .and_then(|rom| rom.path.parent().map(Path::to_path_buf));
    context.session.external_port_selection = DesktopExternalPortSelection::GameLink;
    if config_fell_back && !context.session.test_runner {
        context
            .settings_store
            .persist_machine_preferences(&context.session.config)?;
    }
    clear_live_input_state(context.machine, context.runtime);
    *context.machine = next_machine;
    reset_frontend_timeline_state(context.runtime);
    if let Some(audio_output) = &mut context.runtime.audio_output {
        audio_output.reset_for_session_swap(next_console_model)?;
    }
    if let Some(audio_recorder) = &mut context.runtime.audio_recorder {
        audio_recorder.reset_for_session_swap(next_console_model)?;
    }
    context.runtime.save_sessions = next_save_sessions;
    context.runtime.rtc_sync.resync_to_host_clock();
    context.performance_counter.reset_base_title(
        canvas.window_mut(),
        window_title(context.session, &context.session.config),
    )?;

    if context.runtime.menu_state.is_open() {
        close_menu(event_pump, context.machine, context.runtime)?;
    }

    Ok(())
}

fn deactivate_cgb_infrared_pair(
    canvas: &mut Canvas<Window>,
    context: &mut FrontendActionContext<'_>,
) -> Result<(), String> {
    drain_printed_pages_into_printer_output(
        canvas.window(),
        context.session,
        context.runtime,
        context.machine,
    );
    flush_pending_printer_output(canvas.window(), context.session, context.runtime);

    if context.machine.is_linked_cgb_infrared_two_player()
        || context.machine.is_pokemon_pikachu_color()
        || context.machine.is_pokemon_mystery_gift()
    {
        close_runtime_save_sessions(context.runtime, context.machine)?;
        context.machine.detach_to_single_primary();
    }

    context.session.linked_secondary_rom = None;
    context.session.dmg07_player_count = None;
    context.session.cgb_infrared_link_active = false;
    context.session.pokemon_pikachu_color_active = false;
    context.session.pokemon_mystery_gift_active = false;
    context.session.external_port_selection = DesktopExternalPortSelection::None;
    apply_external_port_selection_to_machine(
        context.machine.primary_machine_mut(),
        DesktopExternalPortSelection::None,
    );
    context.runtime.save_sessions =
        open_save_sessions_for_session(context.session, context.machine)?;
    reset_frontend_timeline_state(context.runtime);
    context.performance_counter.reset_base_title(
        canvas.window_mut(),
        window_title(context.session, &context.session.config),
    )?;
    context.runtime.rtc_sync.resync_to_host_clock();

    Ok(())
}

fn activate_cgb_infrared_same_game(
    event_pump: &sdl3::EventPump,
    canvas: &mut Canvas<Window>,
    context: &mut FrontendActionContext<'_>,
) -> Result<(), String> {
    if !context.session.has_loaded_rom()
        || context.session.config.launch.console_model != DesktopConsoleModel::GameBoyColor
    {
        return Ok(());
    }
    if cgb_infrared_same_game_active(context.session)
        && context.machine.is_linked_cgb_infrared_two_player()
    {
        return Ok(());
    }

    drain_printed_pages_into_printer_output(
        canvas.window(),
        context.session,
        context.runtime,
        context.machine,
    );
    flush_pending_printer_output(canvas.window(), context.session, context.runtime);
    context.runtime.rtc_sync.apply_to_machine(context.machine);

    let Some(primary_rom) = context.session.loaded_rom.clone() else {
        return Ok(());
    };
    let primary_battery_backed_state = uses_battery_backed_hardware_persistence(
        context
            .machine
            .primary_machine()
            .cartridge()
            .persistence_metadata(),
    )
    .then(|| {
        context
            .machine
            .primary_machine()
            .cartridge()
            .persistent_state()
    });

    let loaded = load_cgb_infrared_machines_for_roms(
        &context.session.config,
        &context.session.current_dir,
        &primary_rom.bytes,
        &primary_rom.bytes,
        "activating CGB IR SAME GAME",
    )?;
    for warning in &loaded.boot_rom_fallback_warnings {
        log_boot_rom_fallback_warning(Some(warning));
    }
    write_cartridge_diagnostics(&loaded.diagnostics);

    let effective_config = loaded.effective_config;
    let config_fell_back = effective_config != context.session.config;
    let mut next_machine = loaded.machine;
    if let Some(persistent_state) = primary_battery_backed_state
        && let Err(error) = next_machine
            .primary_machine_mut()
            .restore_cartridge_persistent_state(&persistent_state)
    {
        return Err(format!(
            "failed to restore battery-backed persistence while activating CGB IR SAME GAME: {error:?}"
        ));
    }

    let next_session = DesktopSession {
        config: effective_config.clone(),
        test_runner: context.session.test_runner,
        benchmark: context.session.benchmark.clone(),
        current_dir: context.session.current_dir.clone(),
        loaded_rom: context.session.loaded_rom.clone(),
        linked_secondary_rom: Some(primary_rom),
        dmg07_player_count: None,
        cgb_infrared_link_active: true,
        pokemon_pikachu_color_active: false,
        pokemon_pikachu_color_gift: context.session.pokemon_pikachu_color_gift,
        pokemon_mystery_gift_active: false,
        pokemon_mystery_gift_kind: context.session.pokemon_mystery_gift_kind,
        pokemon_mystery_gift_code: context.session.pokemon_mystery_gift_code,
        last_open_directory: context.session.last_open_directory.clone(),
        recent_roms: context.session.recent_roms.clone(),
        pocket_camera_frame: context.session.pocket_camera_frame.clone(),
        external_port_selection: DesktopExternalPortSelection::None,
    };
    apply_session_pocket_camera_frame_to_desktop_session(&next_session, &mut next_machine)?;
    let next_save_sessions = open_save_sessions_for_session(&next_session, &mut next_machine)?;

    close_runtime_save_sessions(context.runtime, context.machine)?;
    let next_console_model = next_machine.primary_machine().apu().console_model();

    context.session.config = effective_config;
    context.session.linked_secondary_rom = next_session.linked_secondary_rom;
    context.session.dmg07_player_count = None;
    context.session.cgb_infrared_link_active = true;
    context.session.pokemon_pikachu_color_active = false;
    context.session.pokemon_mystery_gift_active = false;
    context.session.last_open_directory = context
        .session
        .linked_secondary_rom
        .as_ref()
        .and_then(|rom| rom.path.parent().map(Path::to_path_buf));
    context.session.external_port_selection = DesktopExternalPortSelection::None;
    if config_fell_back && !context.session.test_runner {
        context
            .settings_store
            .persist_machine_preferences(&context.session.config)?;
    }
    clear_live_input_state(context.machine, context.runtime);
    *context.machine = next_machine;
    reset_frontend_timeline_state(context.runtime);
    if let Some(audio_output) = &mut context.runtime.audio_output {
        audio_output.reset_for_session_swap(next_console_model)?;
    }
    if let Some(audio_recorder) = &mut context.runtime.audio_recorder {
        audio_recorder.reset_for_session_swap(next_console_model)?;
    }
    context.runtime.save_sessions = next_save_sessions;
    context.runtime.rtc_sync.resync_to_host_clock();
    context.performance_counter.reset_base_title(
        canvas.window_mut(),
        window_title(context.session, &context.session.config),
    )?;

    if context.runtime.menu_state.is_open() {
        close_menu(event_pump, context.machine, context.runtime)?;
    }

    Ok(())
}

