fn sync_live_input_state(
    event_pump: &sdl3::EventPump,
    keyboard_bindings: &KeyboardBindings,
    machine: &mut DesktopEmulationSession,
    runtime: &mut FrontendRuntime,
) {
    clear_live_input_state(machine, runtime);
    let session_kind = player_session_kind(machine);
    for slot in PlayerSlot::ALL {
        let Some(route) = input_route_for_player_slot(machine, session_kind, slot) else {
            runtime.player_inputs.input_mut(slot).reset();
            continue;
        };
        let slot_machine = machine_for_player_input_route_mut(machine, slot, route);
        sync_player_keyboard_state(
            event_pump,
            keyboard_bindings,
            route.keyboard_profile,
            route.target,
            runtime.player_inputs.input_mut(slot),
            slot_machine,
        );
    }
    if let Some(gamepad_manager) = &mut runtime.gamepad_manager {
        gamepad_manager.sync_active_gamepad_state(
            runtime.player_inputs.input_mut(PlayerSlot::P1),
            machine
                .machine_for_player_slot_mut(PlayerSlot::P1)
                .expect("P1 should always map to an active desktop machine"),
        );
    }
}

fn clear_live_input_state(machine: &mut DesktopEmulationSession, runtime: &mut FrontendRuntime) {
    let session_kind = player_session_kind(machine);
    for slot in PlayerSlot::ALL {
        let Some(route) = input_route_for_player_slot(machine, session_kind, slot) else {
            runtime.player_inputs.input_mut(slot).reset();
            continue;
        };
        match machine_for_player_input_route_mut(machine, slot, route) {
            Some(machine) => runtime
                .player_inputs
                .input_mut(slot)
                .clear_all_for_target(machine, route.target),
            None => runtime.player_inputs.input_mut(slot).reset(),
        }
    }
}

fn sync_player_keyboard_state(
    event_pump: &sdl3::EventPump,
    keyboard_bindings: &KeyboardBindings,
    keyboard_profile: PlayerKeyboardProfile,
    target: FrontendJoypadTarget,
    input_state: &mut FrontendInputState,
    machine: Option<&mut Machine<TraceSummaryBuffer>>,
) {
    let Some(machine) = machine else {
        input_state.reset();
        return;
    };

    let keyboard_state = event_pump.keyboard_state();
    match keyboard_profile {
        PlayerKeyboardProfile::ConfiguredJoypad => {
            let joypad = keyboard_bindings.joypad;
            let bindings = [
                (JoypadButton::Up, desktop_key_scancode(joypad.up)),
                (JoypadButton::Down, desktop_key_scancode(joypad.down)),
                (JoypadButton::Left, desktop_key_scancode(joypad.left)),
                (JoypadButton::Right, desktop_key_scancode(joypad.right)),
                (JoypadButton::A, desktop_key_scancode(joypad.a)),
                (JoypadButton::B, desktop_key_scancode(joypad.b)),
                (JoypadButton::Select, desktop_key_scancode(joypad.select)),
                (JoypadButton::Start, desktop_key_scancode(joypad.start)),
            ];
            for (joypad_button, scancode) in bindings {
                input_state.set_keyboard_button_for_target(
                    machine,
                    target,
                    joypad_button,
                    keyboard_state.is_scancode_pressed(scancode),
                );
            }
        }
        PlayerKeyboardProfile::LinkedDmg04P2 => {
            for (joypad_button, scancode) in player_slots::LINKED_DMG04_P2_KEYBOARD_BINDINGS {
                input_state.set_keyboard_button_for_target(
                    machine,
                    target,
                    joypad_button,
                    keyboard_state.is_scancode_pressed(scancode),
                );
            }
        }
        PlayerKeyboardProfile::LinkedDmg07P3 => {
            for (joypad_button, scancode) in player_slots::LINKED_DMG07_P3_KEYBOARD_BINDINGS {
                input_state.set_keyboard_button_for_target(
                    machine,
                    target,
                    joypad_button,
                    keyboard_state.is_scancode_pressed(scancode),
                );
            }
        }
        PlayerKeyboardProfile::LinkedDmg07P4 => {
            for (joypad_button, scancode) in player_slots::LINKED_DMG07_P4_KEYBOARD_BINDINGS {
                input_state.set_keyboard_button_for_target(
                    machine,
                    target,
                    joypad_button,
                    keyboard_state.is_scancode_pressed(scancode),
                );
            }
        }
        PlayerKeyboardProfile::Disabled => {
            input_state.reset();
        }
    }
}

fn apply_keyboard_event_to_player_slots(
    runtime: &mut FrontendRuntime,
    machine: &mut DesktopEmulationSession,
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
    pressed: bool,
) {
    let session_kind = player_session_kind(machine);
    let keyboard_bindings = runtime.keyboard_bindings;
    for slot in PlayerSlot::ALL {
        let Some(route) = input_route_for_player_slot(machine, session_kind, slot) else {
            continue;
        };
        let Some(button) = joypad_button_for_player_keyboard_event(
            route.keyboard_profile,
            keyboard_bindings,
            keycode,
            scancode,
        ) else {
            continue;
        };
        let Some(slot_machine) = machine_for_player_input_route_mut(machine, slot, route) else {
            continue;
        };
        runtime
            .player_inputs
            .input_mut(slot)
            .set_keyboard_button_for_target(slot_machine, route.target, button, pressed);
    }
}

fn joypad_button_for_player_keyboard_event(
    keyboard_profile: PlayerKeyboardProfile,
    keyboard_bindings: KeyboardBindings,
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
) -> Option<JoypadButton> {
    match keyboard_profile {
        PlayerKeyboardProfile::ConfiguredJoypad => {
            joypad_button_for_key_event(keyboard_bindings.joypad, keycode, scancode)
        }
        PlayerKeyboardProfile::LinkedDmg04P2 => {
            scancode.and_then(linked_dmg04_p2_button_for_scancode)
        }
        PlayerKeyboardProfile::LinkedDmg07P3 => {
            scancode.and_then(linked_dmg07_p3_button_for_scancode)
        }
        PlayerKeyboardProfile::LinkedDmg07P4 => {
            scancode.and_then(linked_dmg07_p4_button_for_scancode)
        }
        PlayerKeyboardProfile::Disabled => None,
    }
}

fn desktop_key_scancode(binding: DesktopKey) -> Scancode {
    match binding {
        DesktopKey::Escape => Scancode::Escape,
        DesktopKey::ArrowUp => Scancode::Up,
        DesktopKey::ArrowDown => Scancode::Down,
        DesktopKey::ArrowLeft => Scancode::Left,
        DesktopKey::ArrowRight => Scancode::Right,
        DesktopKey::Tab => Scancode::Tab,
        DesktopKey::Backspace => Scancode::Backspace,
        DesktopKey::Return => Scancode::Return,
        DesktopKey::Space => Scancode::Space,
        DesktopKey::R => Scancode::R,
        DesktopKey::X => Scancode::X,
        DesktopKey::Z => Scancode::Z,
        DesktopKey::Digit1 => Scancode::_1,
        DesktopKey::Digit2 => Scancode::_2,
        DesktopKey::Digit3 => Scancode::_3,
        DesktopKey::Digit4 => Scancode::_4,
        DesktopKey::F1 => Scancode::F1,
        DesktopKey::F2 => Scancode::F2,
        DesktopKey::F3 => Scancode::F3,
        DesktopKey::F4 => Scancode::F4,
        DesktopKey::F5 => Scancode::F5,
        DesktopKey::F6 => Scancode::F6,
        DesktopKey::F7 => Scancode::F7,
        DesktopKey::F8 => Scancode::F8,
        DesktopKey::F9 => Scancode::F9,
        DesktopKey::F10 => Scancode::F10,
        DesktopKey::F11 => Scancode::F11,
        DesktopKey::F12 => Scancode::F12,
        DesktopKey::LeftShift => Scancode::LShift,
        DesktopKey::RightShift => Scancode::RShift,
        DesktopKey::LeftControl => Scancode::LCtrl,
        DesktopKey::RightControl => Scancode::RCtrl,
        DesktopKey::LeftAlt => Scancode::LAlt,
        DesktopKey::RightAlt => Scancode::RAlt,
        DesktopKey::LeftGui => Scancode::LGui,
        DesktopKey::RightGui => Scancode::RGui,
    }
}

fn gamepad_event_joystick_id(which: u32) -> sdl3::joystick::JoystickId {
    sdl3::sys::joystick::SDL_JoystickID(which)
}

#[cfg(test)]
fn menu_input_for_key(bindings: MenuKeyboardBindings, keycode: Keycode) -> Option<MenuInput> {
    menu_input_for_key_event(bindings, Some(keycode), None)
}

fn menu_input_for_key_event(
    bindings: MenuKeyboardBindings,
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
) -> Option<MenuInput> {
    if key_event_matches(DesktopKey::Escape, keycode, scancode) {
        return Some(MenuInput::Cancel);
    }

    if key_event_matches(bindings.up, keycode, scancode) {
        Some(MenuInput::Up)
    } else if key_event_matches(bindings.down, keycode, scancode) {
        Some(MenuInput::Down)
    } else if key_event_matches(bindings.confirm, keycode, scancode) {
        Some(MenuInput::Confirm)
    } else if key_event_matches(bindings.cancel, keycode, scancode) {
        Some(MenuInput::Cancel)
    } else {
        None
    }
}

fn menu_input_for_gamepad_button(
    bindings: GamepadMenuBindings,
    button: Button,
) -> Option<MenuInput> {
    let binding = gamepad_button_binding_from_sdl_button(button)?;
    menu_input_for_gamepad_binding(bindings, binding)
}

fn menu_input_for_gamepad_binding(
    bindings: GamepadMenuBindings,
    binding: GamepadButtonBinding,
) -> Option<MenuInput> {
    if binding == bindings.up {
        Some(MenuInput::Up)
    } else if binding == bindings.down {
        Some(MenuInput::Down)
    } else if binding == bindings.confirm {
        Some(MenuInput::Confirm)
    } else if binding == bindings.cancel {
        Some(MenuInput::Cancel)
    } else {
        None
    }
}

fn reset_pokemon_mystery_gift_session(
    session: &DesktopSession,
    rom_bytes: &[u8],
    battery_backed_states: &[Option<PersistentCartState>; PLAYER_SLOT_COUNT],
) -> Result<RebuildMachineResult, String> {
    let loaded = match load_machine_for_rom(&session.config, &session.current_dir, rom_bytes) {
        Ok(result) => result,
        Err(error) => {
            return Err(format_display_error(
                "failed to reload cartridge during Pokemon Mystery Gift reset",
                &error,
            ));
        }
    };
    let mut boot_rom_fallback_warnings = Vec::new();
    if let Some(warning) = loaded.boot_rom_fallback_warning {
        boot_rom_fallback_warnings.push(warning);
    }
    write_cartridge_diagnostics(&loaded.diagnostics);
    let mut reset_machine = DesktopEmulationSession::new_pokemon_mystery_gift(
        loaded.machine,
        session.pokemon_mystery_gift_kind,
        session.pokemon_mystery_gift_code,
    );
    restore_battery_backed_states_by_player_slot(
        &mut reset_machine,
        battery_backed_states,
        "after reset",
    )?;
    apply_session_pocket_camera_frame_to_desktop_session(session, &mut reset_machine)?;

    let effective_config = loaded.effective_config;
    let next_save_sessions = open_save_sessions_for_session(
        &DesktopSession {
            config: effective_config.clone(),
            linked_secondary_rom: None,
            external_port_selection: DesktopExternalPortSelection::None,
            dmg07_player_count: None,
            cgb_infrared_link_active: false,
            pokemon_pikachu_color_active: false,
            pokemon_mystery_gift_active: true,
            ..session.clone()
        },
        &mut reset_machine,
    )?;
    Ok((
        effective_config,
        boot_rom_fallback_warnings,
        reset_machine,
        next_save_sessions,
    ))
}

fn reset_machine(
    main_window: &Window,
    session: &mut DesktopSession,
    machine: &mut DesktopEmulationSession,
    runtime: &mut FrontendRuntime,
    settings_store: &mut DesktopSettingsStore,
) -> Result<(), String> {
    let Some(rom_bytes) = session.rom_bytes() else {
        return Ok(());
    };
    drain_printed_pages_into_printer_output(main_window, session, runtime, machine);
    flush_pending_printer_output(main_window, session, runtime);
    runtime.rtc_sync.apply_to_machine(machine);
    let battery_backed_states = battery_backed_states_by_player_slot(machine);

    close_runtime_save_sessions(runtime, machine)?;

    let (effective_config, boot_rom_fallback_warnings, reset_machine, next_save_sessions) = match (
        session.linked_secondary_rom_bytes(),
        session.cgb_infrared_link_active,
        session.pokemon_pikachu_color_active,
        session.pokemon_mystery_gift_active,
        session.external_port_selection,
        session.dmg07_player_count,
    ) {
        (Some(secondary_rom_bytes), true, _, _, _, _) => {
            let loaded = load_cgb_infrared_machines_for_roms(
                &session.config,
                &session.current_dir,
                rom_bytes,
                secondary_rom_bytes,
                "resetting a CGB IR session",
            )?;
            let boot_rom_fallback_warnings = loaded.boot_rom_fallback_warnings;
            write_cartridge_diagnostics(&loaded.diagnostics);
            let mut reset_machine = loaded.machine;
            restore_battery_backed_states_by_player_slot(
                &mut reset_machine,
                &battery_backed_states,
                "after reset",
            )?;
            apply_session_pocket_camera_frame_to_desktop_session(session, &mut reset_machine)?;

            let effective_config = loaded.effective_config;
            let next_save_sessions = open_save_sessions_for_session(
                &DesktopSession {
                    config: effective_config.clone(),
                    external_port_selection: DesktopExternalPortSelection::None,
                    dmg07_player_count: None,
                    cgb_infrared_link_active: true,
                    pokemon_pikachu_color_active: false,
                    pokemon_mystery_gift_active: false,
                    ..session.clone()
                },
                &mut reset_machine,
            )?;
            (
                effective_config,
                boot_rom_fallback_warnings,
                reset_machine,
                next_save_sessions,
            )
        }
        (
            Some(secondary_rom_bytes),
            false,
            false,
            false,
            DesktopExternalPortSelection::GameLink,
            _,
        ) => {
            let primary_loaded =
                match load_machine_for_rom(&session.config, &session.current_dir, rom_bytes) {
                    Ok(result) => result,
                    Err(error) => {
                        return Err(format_display_error(
                            "failed to reload primary cartridge during linked reset",
                            &error,
                        ));
                    }
                };
            let secondary_loaded = match load_machine_for_rom(
                &session.config,
                &session.current_dir,
                secondary_rom_bytes,
            ) {
                Ok(result) => result,
                Err(error) => {
                    return Err(format_display_error(
                        "failed to reload secondary cartridge during linked reset",
                        &error,
                    ));
                }
            };
            if primary_loaded.effective_config != secondary_loaded.effective_config {
                return Err(
                    "linked reset produced divergent effective configs between the primary and secondary machines"
                        .to_string(),
                );
            }

            let mut boot_rom_fallback_warnings = Vec::new();
            if let Some(warning) = primary_loaded.boot_rom_fallback_warning {
                boot_rom_fallback_warnings.push(warning);
            }
            if let Some(warning) = secondary_loaded.boot_rom_fallback_warning {
                boot_rom_fallback_warnings.push(warning);
            }
            write_cartridge_diagnostics(&primary_loaded.diagnostics);
            write_cartridge_diagnostics(&secondary_loaded.diagnostics);

            let mut reset_machine = DesktopEmulationSession::new_single(primary_loaded.machine);
            reset_machine.attach_secondary_dmg04(secondary_loaded.machine)?;
            restore_battery_backed_states_by_player_slot(
                &mut reset_machine,
                &battery_backed_states,
                "after reset",
            )?;
            apply_session_pocket_camera_frame_to_desktop_session(session, &mut reset_machine)?;

            let effective_config = primary_loaded.effective_config;
            let next_save_sessions = open_save_sessions_for_session(
                &DesktopSession {
                    config: effective_config.clone(),
                    ..session.clone()
                },
                &mut reset_machine,
            )?;
            (
                effective_config,
                boot_rom_fallback_warnings,
                reset_machine,
                next_save_sessions,
            )
        }
        (_, false, true, _, _, _) => {
            let loaded =
                match load_machine_for_rom(&session.config, &session.current_dir, rom_bytes) {
                    Ok(result) => result,
                    Err(error) => {
                        return Err(format_display_error(
                            "failed to reload cartridge during Pokemon Pikachu Color reset",
                            &error,
                        ));
                    }
                };
            let mut boot_rom_fallback_warnings = Vec::new();
            if let Some(warning) = loaded.boot_rom_fallback_warning {
                boot_rom_fallback_warnings.push(warning);
            }
            write_cartridge_diagnostics(&loaded.diagnostics);
            let mut reset_machine = DesktopEmulationSession::new_pokemon_pikachu_color(
                loaded.machine,
                session.pokemon_pikachu_color_gift,
                PokemonPikachuColorRegion::Auto,
            );
            restore_battery_backed_states_by_player_slot(
                &mut reset_machine,
                &battery_backed_states,
                "after reset",
            )?;
            apply_session_pocket_camera_frame_to_desktop_session(session, &mut reset_machine)?;

            let effective_config = loaded.effective_config;
            let next_save_sessions = open_save_sessions_for_session(
                &DesktopSession {
                    config: effective_config.clone(),
                    linked_secondary_rom: None,
                    external_port_selection: DesktopExternalPortSelection::None,
                    dmg07_player_count: None,
                    cgb_infrared_link_active: false,
                    pokemon_pikachu_color_active: true,
                    pokemon_mystery_gift_active: false,
                    ..session.clone()
                },
                &mut reset_machine,
            )?;
            (
                effective_config,
                boot_rom_fallback_warnings,
                reset_machine,
                next_save_sessions,
            )
        }
        (_, false, false, true, _, _) => {
            reset_pokemon_mystery_gift_session(session, rom_bytes, &battery_backed_states)?
        }
        (
            _,
            false,
            false,
            false,
            DesktopExternalPortSelection::FourPlayerAdapter,
            Some(player_count),
        ) => {
            let loaded = load_dmg07_machines_for_rom(
                &session.config,
                &session.current_dir,
                rom_bytes,
                player_count,
                "resetting a DMG-07 session",
            )?;
            let boot_rom_fallback_warnings = loaded.boot_rom_fallback_warnings;
            write_cartridge_diagnostics(&loaded.diagnostics);
            let mut reset_machine = loaded.machine;
            restore_battery_backed_states_by_player_slot(
                &mut reset_machine,
                &battery_backed_states,
                "after reset",
            )?;
            apply_session_pocket_camera_frame_to_desktop_session(session, &mut reset_machine)?;

            let effective_config = loaded.effective_config;
            let next_save_sessions = open_save_sessions_for_session(
                &DesktopSession {
                    config: effective_config.clone(),
                    linked_secondary_rom: None,
                    external_port_selection: DesktopExternalPortSelection::FourPlayerAdapter,
                    dmg07_player_count: Some(player_count),
                    cgb_infrared_link_active: false,
                    pokemon_pikachu_color_active: false,
                    pokemon_mystery_gift_active: false,
                    ..session.clone()
                },
                &mut reset_machine,
            )?;
            (
                effective_config,
                boot_rom_fallback_warnings,
                reset_machine,
                next_save_sessions,
            )
        }
        _ => {
            let loaded =
                match load_machine_for_rom(&session.config, &session.current_dir, rom_bytes) {
                    Ok(result) => result,
                    Err(error) => {
                        return Err(format_display_error(
                            "failed to reload cartridge during reset",
                            &error,
                        ));
                    }
                };
            let mut boot_rom_fallback_warnings = Vec::new();
            if let Some(warning) = loaded.boot_rom_fallback_warning {
                boot_rom_fallback_warnings.push(warning);
            }
            write_cartridge_diagnostics(&loaded.diagnostics);
            let mut reset_machine = DesktopEmulationSession::new_single(loaded.machine);
            restore_battery_backed_states_by_player_slot(
                &mut reset_machine,
                &battery_backed_states,
                "after reset",
            )?;
            apply_external_port_selection_to_machine(
                reset_machine.primary_machine_mut(),
                session.external_port_selection,
            );
            apply_session_pocket_camera_frame_to_desktop_session(session, &mut reset_machine)?;

            let effective_config = loaded.effective_config;
            let next_save_sessions = open_save_sessions_for_session(
                &DesktopSession {
                    config: effective_config.clone(),
                    linked_secondary_rom: None,
                    dmg07_player_count: None,
                    cgb_infrared_link_active: false,
                    pokemon_pikachu_color_active: false,
                    pokemon_mystery_gift_active: false,
                    ..session.clone()
                },
                &mut reset_machine,
            )?;
            (
                effective_config,
                boot_rom_fallback_warnings,
                reset_machine,
                next_save_sessions,
            )
        }
    };

    for warning in &boot_rom_fallback_warnings {
        log_boot_rom_fallback_warning(Some(warning));
    }
    let config_fell_back = effective_config != session.config;
    session.config = effective_config;
    if config_fell_back && !session.test_runner {
        settings_store.persist_machine_preferences(&session.config)?;
    }
    let reset_console_model = reset_machine.primary_machine().apu().console_model();

    clear_live_input_state(machine, runtime);
    *machine = reset_machine;
    reset_frontend_timeline_state(runtime);
    if let Some(audio_output) = &mut runtime.audio_output {
        audio_output.reset_for_session_swap(reset_console_model)?;
    }
    if let Some(audio_recorder) = &mut runtime.audio_recorder {
        audio_recorder.reset_for_session_swap(reset_console_model)?;
    }
    runtime.save_sessions = next_save_sessions;
    runtime.rtc_sync.resync_to_host_clock();
    Ok(())
}

fn save_screenshot_for_session(
    session: &DesktopSession,
    machine: &DesktopEmulationSession,
    video_options: &VideoOptions,
) -> Result<PathBuf, String> {
    let dimensions =
        framebuffer_dimensions_for_session(machine, video_options, session.has_loaded_rom());
    let rendered = screenshot_output::render_screenshot(
        framebuffer_render_input_for_session(
            machine,
            dimensions,
            video_options,
            session.has_loaded_rom(),
        ),
        video_options,
    );
    let output_path = screenshot_output::resolve_next_screenshot_output_path(
        session.rom_path(),
        session.current_dir.as_path(),
    )?;
    screenshot_output::save_rendered_screenshot_png(&rendered, &output_path)?;
    Ok(output_path)
}

fn save_screenshot_for_session_to_path(
    machine: &DesktopEmulationSession,
    video_options: &VideoOptions,
    output_path: &Path,
    session_has_loaded_rom: bool,
) -> Result<(), String> {
    let dimensions =
        framebuffer_dimensions_for_session(machine, video_options, session_has_loaded_rom);
    let rendered = screenshot_output::render_screenshot(
        framebuffer_render_input_for_session(
            machine,
            dimensions,
            video_options,
            session_has_loaded_rom,
        ),
        video_options,
    );
    if let Some(parent) = output_path.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent).map_err(|error| {
            format!(
                "failed to create benchmark screenshot directory {}: {error}",
                parent.display()
            )
        })?;
    }
    screenshot_output::save_rendered_screenshot_png(&rendered, output_path)
}

fn write_benchmark_artifacts_for_session(
    session: &DesktopSession,
    machine: &DesktopEmulationSession,
    video_options: &VideoOptions,
    performance_counter: &PerformanceCounter,
) -> Result<(), String> {
    let Some(benchmark) = session.benchmark.as_ref() else {
        return Ok(());
    };

    let elapsed_seconds = benchmark.started_at.elapsed().as_secs_f64();
    let executed_tcycles = machine
        .primary_machine()
        .next_t_cycle()
        .get()
        .saturating_sub(benchmark.started_t_cycle);
    let screenshot_path = benchmark
        .case
        .screenshot
        .then(|| frontend_screenshot_path(GB_DESKTOP_FRONTEND, &benchmark.case.artifact_id));
    if let Some(screenshot_path) = &screenshot_path {
        let output_path = resolve_path(session.current_dir.as_path(), screenshot_path);
        save_screenshot_for_session_to_path(
            machine,
            video_options,
            &output_path,
            session.has_loaded_rom(),
        )?;
    }
    if benchmark.case.stats {
        let stats_path = frontend_stats_path(GB_DESKTOP_FRONTEND, &benchmark.case.artifact_id);
        let stats = BenchmarkStats::new(
            GB_DESKTOP_FRONTEND,
            &benchmark.case,
            session.test_runner,
            performance_counter.presented_frames_total,
            elapsed_seconds,
            Some(executed_tcycles),
            screenshot_path.as_deref(),
        );
        let encoded_stats = encode_stats_toml(&stats)
            .map_err(|error| format!("failed to encode benchmark stats TOML: {error}"))?;
        write_text_file_with_parent(
            &resolve_path(session.current_dir.as_path(), &stats_path),
            &encoded_stats,
        )?;
    }

    Ok(())
}

fn write_text_file_with_parent(path: &Path, text: &str) -> Result<(), String> {
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent).map_err(|error| {
            format!(
                "failed to create artifact directory {}: {error}",
                parent.display()
            )
        })?;
    }
    fs::write(path, text).map_err(|error| format!("failed to write {}: {error}", path.display()))
}

fn toggle_fullscreen(window: &mut Window) -> Result<(), String> {
    let target_state = window.fullscreen_state() == FullscreenType::Off;
    map_display_result(
        window.set_fullscreen(target_state),
        "failed to toggle SDL3 fullscreen state",
    )
}

fn set_fullscreen_state(window: &mut Window, enabled: bool) -> Result<(), String> {
    if (window.fullscreen_state() != FullscreenType::Off) == enabled {
        return Ok(());
    }

    map_display_result(
        window.set_fullscreen(enabled),
        "failed to set SDL3 fullscreen state",
    )
}

fn apply_renderer_vsync(
    canvas: &mut Canvas<Window>,
    frame_pacer: &mut FramePacer,
    vsync_enabled: bool,
) -> Result<(), String> {
    let interval = if vsync_enabled {
        1
    } else {
        sys::render::SDL_RENDERER_VSYNC_DISABLED
    };
    // SDL3 exposes render-vsync control on the renderer, not on the window.
    let success = unsafe { sys::render::SDL_SetRenderVSync(canvas.raw(), interval) };
    if !success {
        return Err(format!(
            "failed to configure SDL3 renderer vsync: {}",
            sdl3::get_error()
        ));
    }

    frame_pacer.set_vsync_enabled(vsync_enabled);
    Ok(())
}

#[cfg(test)]
fn apply_window_scale(window: &mut Window, scale: u8) -> Result<(), String> {
    apply_window_scale_for_dimensions(
        window,
        scale,
        FramebufferDimensions {
            width: FRAMEBUFFER_WIDTH,
            height: FRAMEBUFFER_HEIGHT,
        },
    )
}

fn apply_window_scale_for_dimensions(
    window: &mut Window,
    scale: u8,
    dimensions: FramebufferDimensions,
) -> Result<(), String> {
    let scale = u32::from(scale.max(1));
    let width = dimensions
        .width
        .checked_mul(scale)
        .ok_or_else(|| overflow_error("window width overflowed while applying window scale"))?;
    let height = dimensions
        .height
        .checked_mul(scale)
        .ok_or_else(|| overflow_error("window height overflowed while applying window scale"))?;
    map_display_result(
        window.set_size(width, height),
        "failed to resize SDL3 window",
    )
}

fn apply_canvas_video_options_for_dimensions(
    canvas: &mut Canvas<Window>,
    video_options: &VideoOptions,
    dimensions: FramebufferDimensions,
) -> Result<(), String> {
    let presentation_mode = if video_options.integer_scale {
        sys::render::SDL_LOGICAL_PRESENTATION_INTEGER_SCALE
    } else {
        sys::render::SDL_LOGICAL_PRESENTATION_LETTERBOX
    };
    map_display_result(
        canvas.set_logical_size(dimensions.width, dimensions.height, presentation_mode),
        "failed to configure SDL3 logical presentation",
    )
}

fn sync_audio_playback_state(
    machine: &DesktopEmulationSession,
    runtime: &FrontendRuntime,
) -> Result<(), String> {
    let Some(audio_output) = runtime.audio_output.as_ref() else {
        return Ok(());
    };

    if emulation_paused(audio_source_machine(machine), runtime) {
        audio_output.pause()
    } else {
        audio_output.resume()
    }
}

fn sync_fast_forward_audio_state(
    runtime: &mut FrontendRuntime,
    fast_forward_active: bool,
) -> Result<(), String> {
    if fast_forward_active {
        if !runtime.fast_forward_audio_suppressed {
            if let Some(audio_output) = &mut runtime.audio_output {
                audio_output.clear_buffer()?;
            }
            runtime.fast_forward_audio_suppressed = true;
        }
    } else if runtime.fast_forward_audio_suppressed {
        if let Some(audio_output) = &mut runtime.audio_output {
            audio_output.clear_buffer()?;
        }
        runtime.fast_forward_audio_suppressed = false;
    }
    Ok(())
}

fn sync_fast_forward_host_pacing_state(
    canvas: &mut Canvas<Window>,
    frame_pacer: &mut FramePacer,
    runtime: &mut FrontendRuntime,
    fast_forward_active: bool,
) -> Result<(), String> {
    if fast_forward_active && runtime.video_options.vsync && !runtime.fast_forward_vsync_suppressed
    {
        apply_renderer_vsync(canvas, frame_pacer, false)?;
        runtime.fast_forward_vsync_suppressed = true;
    } else if !fast_forward_active && runtime.fast_forward_vsync_suppressed {
        apply_renderer_vsync(canvas, frame_pacer, runtime.video_options.vsync)?;
        runtime.fast_forward_vsync_suppressed = false;
    }
    Ok(())
}

fn framebuffer_dimensions_for_session(
    machine: &DesktopEmulationSession,
    video_options: &VideoOptions,
    session_has_loaded_rom: bool,
) -> FramebufferDimensions {
    let layout = view_layout_for_session(player_session_kind(machine));
    let cell_dimensions =
        framebuffer_cell_dimensions_for_session(machine, video_options, session_has_loaded_rom);
    FramebufferDimensions {
        width: cell_dimensions.width * layout.columns as u32,
        height: cell_dimensions.height * layout.rows as u32,
    }
}

fn framebuffer_cell_dimensions_for_session(
    machine: &DesktopEmulationSession,
    video_options: &VideoOptions,
    session_has_loaded_rom: bool,
) -> FramebufferDimensions {
    let layout = view_layout_for_session(player_session_kind(machine));
    layout
        .slots
        .into_iter()
        .flatten()
        .filter_map(|slot| machine.machine_for_player_slot(slot))
        .map(|machine| {
            framebuffer_panel_dimensions_for_machine(machine, video_options, session_has_loaded_rom)
        })
        .fold(
            FramebufferDimensions {
                width: FRAMEBUFFER_WIDTH,
                height: FRAMEBUFFER_HEIGHT,
            },
            |acc, dimensions| FramebufferDimensions {
                width: acc.width.max(dimensions.width),
                height: acc.height.max(dimensions.height),
            },
        )
}

fn framebuffer_panel_dimensions_for_machine(
    machine: &Machine<TraceSummaryBuffer>,
    video_options: &VideoOptions,
    session_has_loaded_rom: bool,
) -> FramebufferDimensions {
    if session_has_loaded_rom
        && machine.sgb_host().profile().is_some()
        && video_options.show_sgb_border
    {
        FramebufferDimensions {
            width: SGB_HOST_FRAMEBUFFER_WIDTH,
            height: SGB_HOST_FRAMEBUFFER_HEIGHT,
        }
    } else {
        FramebufferDimensions {
            width: FRAMEBUFFER_WIDTH,
            height: FRAMEBUFFER_HEIGHT,
        }
    }
}

fn framebuffer_cell_dimensions_for_panels(
    panels: &[Option<FramebufferPanelInput<'_>>; PLAYER_SLOT_COUNT],
) -> FramebufferDimensions {
    panels
        .iter()
        .filter_map(|panel| panel.as_ref())
        .map(|panel| panel.dimensions)
        .fold(
            FramebufferDimensions {
                width: FRAMEBUFFER_WIDTH,
                height: FRAMEBUFFER_HEIGHT,
            },
            |acc, dimensions| FramebufferDimensions {
                width: acc.width.max(dimensions.width),
                height: acc.height.max(dimensions.height),
            },
        )
}

fn framebuffer_panel_input_for_player_slot<'a>(
    machine: &'a DesktopEmulationSession,
    slot: PlayerSlot,
    display_palette: DisplayPalette,
    video_options: &VideoOptions,
    session_has_loaded_rom: bool,
) -> Option<FramebufferPanelInput<'a>> {
    let machine = machine.machine_for_player_slot(slot)?;
    let sgb_framebuffer_rgb555 = if session_has_loaded_rom && machine.sgb_host().profile().is_some()
    {
        if video_options.show_sgb_border {
            machine.sgb_framebuffer_rgb555()
        } else {
            machine.sgb_lcd_framebuffer_rgb555()
        }
    } else {
        None
    };
    let dimensions = if sgb_framebuffer_rgb555.is_some() {
        framebuffer_panel_dimensions_for_machine(machine, video_options, session_has_loaded_rom)
    } else {
        FramebufferDimensions {
            width: FRAMEBUFFER_WIDTH,
            height: FRAMEBUFFER_HEIGHT,
        }
    };
    Some(FramebufferPanelInput {
        dimensions,
        framebuffer: machine.ppu().framebuffer(),
        framebuffer_layer_sources: machine.ppu().framebuffer_layer_sources(),
        bgwin_framebuffer: machine.ppu().framebuffer_bgwin_panel_shades(),
        backdrop_framebuffer: machine.ppu().framebuffer_backdrop_panel_shades(),
        bgwin_framebuffer_layer_sources: machine.ppu().framebuffer_bgwin_layer_sources(),
        display_palette,
        cgb_framebuffer_rgb555: machine.ppu().cgb_framebuffer_rgb555(),
        sgb_framebuffer_rgb555,
    })
}

fn framebuffer_render_input_for_session<'a>(
    machine: &'a DesktopEmulationSession,
    dimensions: FramebufferDimensions,
    video_options: &VideoOptions,
    session_has_loaded_rom: bool,
) -> FramebufferRenderInput<'a> {
    let layout = view_layout_for_session(player_session_kind(machine));
    let display_palette = display_palette_for_desktop_palette(video_options.display_palette);
    FramebufferRenderInput {
        dimensions,
        panels: layout.slots.map(|slot| {
            slot.and_then(|slot| {
                framebuffer_panel_input_for_player_slot(
                    machine,
                    slot,
                    display_palette,
                    video_options,
                    session_has_loaded_rom,
                )
            })
        }),
    }
}

fn framebuffer_pitch_bytes_for_dimensions(dimensions: FramebufferDimensions) -> usize {
    dimensions.width as usize * 3
}

struct FrameBlendGammaTables {
    half: Vec<u8>,
}

impl FrameBlendGammaTables {
    fn new() -> Self {
        Self {
            half: frame_blend_gamma_table(0.5),
        }
    }

    fn table_for(&self, mode: DesktopFrameBlendingMode) -> Option<&[u8]> {
        match mode {
            DesktopFrameBlendingMode::Off => None,
            DesktopFrameBlendingMode::On => Some(&self.half),
        }
    }
}

fn frame_blend_gamma_tables() -> &'static FrameBlendGammaTables {
    static TABLES: OnceLock<FrameBlendGammaTables> = OnceLock::new();
    TABLES.get_or_init(FrameBlendGammaTables::new)
}

fn frame_blend_gamma_table(previous_weight: f32) -> Vec<u8> {
    const GAMMA: f32 = 2.2;
    let current_weight = 1.0 - previous_weight;
    let mut table = vec![0_u8; 256 * 256];
    for current in 0..=u8::MAX {
        let current_linear = (f32::from(current) / 255.0).powf(GAMMA);
        for previous in 0..=u8::MAX {
            let previous_linear = (f32::from(previous) / 255.0).powf(GAMMA);
            let blended = (current_linear * current_weight + previous_linear * previous_weight)
                .powf(1.0 / GAMMA);
            table[frame_blend_table_index(current, previous)] =
                (blended * 255.0).round().clamp(0.0, 255.0) as u8;
        }
    }
    table
}

fn frame_blend_table_index(current: u8, previous: u8) -> usize {
    usize::from(current) * 256 + usize::from(previous)
}

fn blend_rgb24_frames(
    target_rgb_frame: &mut [u8],
    current_rgb_frame: &[u8],
    previous_rgb_frame: &[u8],
    dimensions: FramebufferDimensions,
    mode: DesktopFrameBlendingMode,
) {
    if mode == DesktopFrameBlendingMode::Off
        || target_rgb_frame.len() != current_rgb_frame.len()
        || target_rgb_frame.len() != previous_rgb_frame.len()
    {
        return;
    }

    let tables = frame_blend_gamma_tables();
    let Some(table) = tables.table_for(mode) else {
        return;
    };
    let pitch = framebuffer_pitch_bytes_for_dimensions(dimensions);
    let height = dimensions.height as usize;
    for y in 0..height {
        let row_start = y * pitch;
        let row_end = row_start.saturating_add(pitch).min(target_rgb_frame.len());
        for index in row_start..row_end {
            target_rgb_frame[index] =
                table[frame_blend_table_index(current_rgb_frame[index], previous_rgb_frame[index])];
        }
    }
}

fn bgwin_layer_source_visible(
    video_options: &VideoOptions,
    source: PpuFramebufferLayerSource,
) -> bool {
    match source {
        PpuFramebufferLayerSource::Backdrop => false,
        PpuFramebufferLayerSource::Background => video_options.show_background,
        PpuFramebufferLayerSource::Window => video_options.show_window,
        PpuFramebufferLayerSource::Object => false,
    }
}

fn composite_framebuffer_panel_shade(
    final_shade: u8,
    final_source: PpuFramebufferLayerSource,
    bgwin_shade: u8,
    bgwin_source: PpuFramebufferLayerSource,
    backdrop_shade: u8,
    video_options: &VideoOptions,
) -> u8 {
    if video_options.show_objects && final_source == PpuFramebufferLayerSource::Object {
        return final_shade;
    }

    if matches!(
        final_source,
        PpuFramebufferLayerSource::Background | PpuFramebufferLayerSource::Window
    ) {
        if bgwin_layer_source_visible(video_options, final_source) {
            return final_shade;
        }
        return backdrop_shade;
    }

    if bgwin_layer_source_visible(video_options, bgwin_source) {
        bgwin_shade
    } else {
        backdrop_shade
    }
}

fn framebuffer_texture_scale_mode(video_options: &VideoOptions) -> ScaleMode {
    if video_options.presentation_filter {
        ScaleMode::Linear
    } else {
        ScaleMode::Nearest
    }
}

fn sync_framebuffer_texture_video_options(
    texture: &mut sdl3::render::Texture<'_>,
    video_options: &VideoOptions,
) {
    let expected_scale_mode = framebuffer_texture_scale_mode(video_options);
    if texture.scale_mode() != expected_scale_mode {
        texture.set_scale_mode(expected_scale_mode);
    }
}

fn create_framebuffer_texture<'a>(
    texture_creator: &'a TextureCreator<WindowContext>,
    dimensions: FramebufferDimensions,
) -> Result<sdl3::render::Texture<'a>, String> {
    map_display_result(
        texture_creator.create_texture_streaming(
            PixelFormat::RGB24,
            dimensions.width,
            dimensions.height,
        ),
        "failed to create framebuffer texture",
    )
}

fn sync_framebuffer_presentation_resources<'a>(
    canvas: &mut Canvas<Window>,
    texture_creator: &'a TextureCreator<WindowContext>,
    texture: &mut sdl3::render::Texture<'a>,
    rgb_frame: &mut Vec<u8>,
    current_dimensions: &mut FramebufferDimensions,
    source: FramebufferPresentationSource<'_>,
) -> Result<(), String> {
    let next_dimensions = framebuffer_dimensions_for_session(
        source.machine,
        source.video_options,
        source.session_has_loaded_rom,
    );
    if next_dimensions == *current_dimensions {
        return Ok(());
    }

    *texture = create_framebuffer_texture(texture_creator, next_dimensions)?;
    rgb_frame.resize(
        next_dimensions.height as usize * framebuffer_pitch_bytes_for_dimensions(next_dimensions),
        0,
    );
    if canvas.window().fullscreen_state() == FullscreenType::Off {
        apply_window_scale_for_dimensions(
            canvas.window_mut(),
            source.video_options.window_scale,
            next_dimensions,
        )?;
    }
    apply_canvas_video_options_for_dimensions(canvas, source.video_options, next_dimensions)?;
    *current_dimensions = next_dimensions;
    Ok(())
}

fn write_framebuffer_region(
    target_rgb_frame: &mut [u8],
    target_dimensions: FramebufferDimensions,
    target_origin_x: usize,
    target_origin_y: usize,
    source_panel: FramebufferPanelInput<'_>,
    video_options: &VideoOptions,
) {
    if let Some(sgb_framebuffer_rgb555) = source_panel.sgb_framebuffer_rgb555.as_deref() {
        write_rgb555_framebuffer_region(
            target_rgb_frame,
            target_dimensions,
            target_origin_x,
            target_origin_y,
            source_panel.dimensions,
            sgb_framebuffer_rgb555,
        );
        return;
    }

    if let Some(cgb_framebuffer_rgb555) = source_panel.cgb_framebuffer_rgb555 {
        write_rgb555_framebuffer_region(
            target_rgb_frame,
            target_dimensions,
            target_origin_x,
            target_origin_y,
            source_panel.dimensions,
            cgb_framebuffer_rgb555,
        );
        return;
    }

    write_monochrome_framebuffer_region(
        target_rgb_frame,
        target_dimensions,
        target_origin_x,
        target_origin_y,
        source_panel,
        video_options,
    );
}

fn write_rgb555_framebuffer_region(
    target_rgb_frame: &mut [u8],
    target_dimensions: FramebufferDimensions,
    target_origin_x: usize,
    target_origin_y: usize,
    source_dimensions: FramebufferDimensions,
    framebuffer_rgb555: &[u16],
) {
    let target_pitch_bytes = framebuffer_pitch_bytes_for_dimensions(target_dimensions);
    let target_width = target_dimensions.width as usize;
    let target_height = target_dimensions.height as usize;
    let source_width = source_dimensions.width as usize;
    let source_height = source_dimensions.height as usize;
    for y in 0..source_height {
        if target_origin_y + y >= target_height {
            break;
        }
        for x in 0..source_width {
            if target_origin_x + x >= target_width {
                break;
            }

            let source_index = y * source_width + x;
            let Some(&rgb555_pixel) = framebuffer_rgb555.get(source_index) else {
                continue;
            };
            let target_pixel_index =
                (target_origin_y + y) * target_pitch_bytes + ((target_origin_x + x) * 3);
            let [r, g, b] = rgb555_to_rgb888(rgb555_pixel);
            target_rgb_frame[target_pixel_index] = r;
            target_rgb_frame[target_pixel_index + 1] = g;
            target_rgb_frame[target_pixel_index + 2] = b;
        }
    }
}

fn rgb555_to_rgb888(color: u16) -> [u8; 3] {
    let red = (color & 0x001F) as u8;
    let green = ((color >> 5) & 0x001F) as u8;
    let blue = ((color >> 10) & 0x001F) as u8;
    [
        scale_5_bit_to_8_bit(red),
        scale_5_bit_to_8_bit(green),
        scale_5_bit_to_8_bit(blue),
    ]
}

fn scale_5_bit_to_8_bit(component: u8) -> u8 {
    (component << 3) | (component >> 2)
}

fn write_monochrome_framebuffer_region(
    target_rgb_frame: &mut [u8],
    target_dimensions: FramebufferDimensions,
    target_origin_x: usize,
    target_origin_y: usize,
    source_panel: FramebufferPanelInput<'_>,
    video_options: &VideoOptions,
) {
    let target_pitch_bytes = framebuffer_pitch_bytes_for_dimensions(target_dimensions);
    let target_width = target_dimensions.width as usize;
    let target_height = target_dimensions.height as usize;
    let source_width = source_panel.dimensions.width as usize;
    let source_height = source_panel.dimensions.height as usize;
    for y in 0..source_height {
        if target_origin_y + y >= target_height {
            break;
        }
        for x in 0..source_width {
            if target_origin_x + x >= target_width {
                break;
            }

            let source_index = y * source_width + x;
            let Some(&framebuffer_shade) = source_panel.framebuffer.get(source_index) else {
                continue;
            };
            let Some(&framebuffer_source) =
                source_panel.framebuffer_layer_sources.get(source_index)
            else {
                continue;
            };
            let Some(&bgwin_shade) = source_panel.bgwin_framebuffer.get(source_index) else {
                continue;
            };
            let Some(&bgwin_source) = source_panel
                .bgwin_framebuffer_layer_sources
                .get(source_index)
            else {
                continue;
            };
            let Some(&backdrop_shade) = source_panel.backdrop_framebuffer.get(source_index) else {
                continue;
            };
            let target_pixel_index =
                (target_origin_y + y) * target_pitch_bytes + ((target_origin_x + x) * 3);
            let panel_shade = composite_framebuffer_panel_shade(
                framebuffer_shade,
                framebuffer_source,
                bgwin_shade,
                bgwin_source,
                backdrop_shade,
                video_options,
            );
            let [r, g, b] = source_panel.display_palette.shade_rgb(panel_shade);
            target_rgb_frame[target_pixel_index] = r;
            target_rgb_frame[target_pixel_index + 1] = g;
            target_rgb_frame[target_pixel_index + 2] = b;
        }
    }
}

fn render_frame(
    canvas: &mut Canvas<Window>,
    texture: &mut sdl3::render::Texture<'_>,
    rgb_frame: &mut [u8],
    framebuffer: FramebufferRenderInput<'_>,
    video_options: &VideoOptions,
    presentation: RenderPresentationInput<'_>,
) -> Result<Duration, String> {
    let RenderPresentationInput {
        frame_blending_state,
        menu_state,
        hud,
    } = presentation;
    let menu_open = menu_state.is_some();
    apply_canvas_video_options_for_dimensions(canvas, video_options, framebuffer.dimensions)?;
    sync_framebuffer_texture_video_options(texture, video_options);
    rgb_frame.fill(0);
    let cell_dimensions = framebuffer_cell_dimensions_for_panels(&framebuffer.panels);
    let columns = (framebuffer.dimensions.width / cell_dimensions.width).max(1) as usize;
    for (panel_index, panel) in framebuffer.panels.into_iter().enumerate() {
        let Some(panel) = panel else {
            continue;
        };
        let column = panel_index % columns;
        let row = panel_index / columns;
        write_framebuffer_region(
            rgb_frame,
            framebuffer.dimensions,
            column * cell_dimensions.width as usize,
            row * cell_dimensions.height as usize,
            panel,
            video_options,
        );
    }
    if let Some(frame_blending_state) = frame_blending_state {
        frame_blending_state.apply(
            rgb_frame,
            framebuffer.dimensions,
            video_options.frame_blending,
        );
    }
    if let Some((menu_state, menu_presentation)) = menu_state {
        menu_state.render_overlay(
            rgb_frame,
            framebuffer.dimensions.width as usize,
            framebuffer.dimensions.height as usize,
            menu_presentation,
        );
    }
    if !menu_open
        && video_options.show_performance_hud
        && let Some(snapshot) = hud.performance
    {
        render_performance_hud(
            rgb_frame,
            framebuffer.dimensions.width as usize,
            framebuffer.dimensions.height as usize,
            snapshot,
        );
    }
    if !menu_open
        && video_options.show_cgb_infrared_helper
        && let Some(snapshot) = hud.cgb_ir
    {
        render_cgb_ir_indicator(
            rgb_frame,
            framebuffer.dimensions.width as usize,
            framebuffer.dimensions.height as usize,
            snapshot,
        );
    }
    if !menu_open && hud.rewind_indicator {
        render_rewind_indicator(
            rgb_frame,
            framebuffer.dimensions.width as usize,
            framebuffer.dimensions.height as usize,
        );
    }
    if !menu_open && hud.fast_forward_indicator {
        render_fast_forward_indicator(
            rgb_frame,
            framebuffer.dimensions.width as usize,
            framebuffer.dimensions.height as usize,
        );
    }

    map_display_result(
        texture.update(
            None,
            rgb_frame,
            framebuffer_pitch_bytes_for_dimensions(framebuffer.dimensions),
        ),
        "failed to update framebuffer texture",
    )?;
    canvas.set_draw_color(Color::RGB(0, 0, 0));
    canvas.clear();
    map_display_result(
        canvas.copy(texture, None, None),
        "failed to present framebuffer texture",
    )?;
    let present_started_at = Instant::now();
    canvas.present();
    Ok(present_started_at.elapsed())
}

fn write_cartridge_diagnostics(diagnostics: &[CartridgeDiagnostic]) {
    for diagnostic in diagnostics {
        eprintln!(
            "{}: {}",
            diagnostic_severity_name(diagnostic.severity),
            diagnostic.message
        );
    }
}

fn diagnostic_severity_name(severity: CartridgeDiagnosticSeverity) -> &'static str {
    match severity {
        CartridgeDiagnosticSeverity::Warning => "warning",
        CartridgeDiagnosticSeverity::Error => "error",
    }
}

#[cfg(test)]
fn joypad_button_for_key(
    bindings: JoypadKeyboardBindings,
    keycode: Keycode,
) -> Option<JoypadButton> {
    joypad_button_for_key_event(bindings, Some(keycode), None)
}

fn joypad_button_for_key_event(
    bindings: JoypadKeyboardBindings,
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
) -> Option<JoypadButton> {
    if key_event_matches(bindings.up, keycode, scancode) {
        Some(JoypadButton::Up)
    } else if key_event_matches(bindings.down, keycode, scancode) {
        Some(JoypadButton::Down)
    } else if key_event_matches(bindings.left, keycode, scancode) {
        Some(JoypadButton::Left)
    } else if key_event_matches(bindings.right, keycode, scancode) {
        Some(JoypadButton::Right)
    } else if key_event_matches(bindings.a, keycode, scancode) {
        Some(JoypadButton::A)
    } else if key_event_matches(bindings.b, keycode, scancode) {
        Some(JoypadButton::B)
    } else if key_event_matches(bindings.select, keycode, scancode) {
        Some(JoypadButton::Select)
    } else if key_event_matches(bindings.start, keycode, scancode) {
        Some(JoypadButton::Start)
    } else {
        None
    }
}

#[cfg(test)]
fn hotkey_action(keyboard_bindings: &KeyboardBindings, keycode: Keycode) -> HotkeyAction {
    hotkey_action_for_key_event(keyboard_bindings, Some(keycode), None)
}

fn hotkey_action_for_key_event(
    keyboard_bindings: &KeyboardBindings,
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
) -> HotkeyAction {
    if key_event_matches(keyboard_bindings.hotkeys.save_battery, keycode, scancode) {
        HotkeyAction::ManualSave
    } else if key_event_matches(keyboard_bindings.hotkeys.save_state, keycode, scancode) {
        HotkeyAction::SaveState
    } else if key_event_matches(keyboard_bindings.hotkeys.load_state, keycode, scancode) {
        HotkeyAction::LoadState
    } else if key_event_matches(keyboard_bindings.hotkeys.state_slot_1, keycode, scancode) {
        HotkeyAction::SelectStateSlot(1)
    } else if key_event_matches(keyboard_bindings.hotkeys.state_slot_2, keycode, scancode) {
        HotkeyAction::SelectStateSlot(2)
    } else if key_event_matches(keyboard_bindings.hotkeys.state_slot_3, keycode, scancode) {
        HotkeyAction::SelectStateSlot(3)
    } else if key_event_matches(keyboard_bindings.hotkeys.state_slot_4, keycode, scancode) {
        HotkeyAction::SelectStateSlot(4)
    } else if key_event_matches(keyboard_bindings.hotkeys.reset, keycode, scancode) {
        HotkeyAction::Reset
    } else if key_event_matches(keyboard_bindings.hotkeys.rewind, keycode, scancode) {
        HotkeyAction::Rewind
    } else if key_event_matches(keyboard_bindings.hotkeys.fast_forward, keycode, scancode) {
        HotkeyAction::FastForward
    } else if key_event_matches(
        keyboard_bindings.hotkeys.toggle_fullscreen,
        keycode,
        scancode,
    ) {
        HotkeyAction::ToggleFullscreen
    } else if key_event_matches(
        keyboard_bindings.hotkeys.toggle_performance_hud,
        keycode,
        scancode,
    ) {
        HotkeyAction::TogglePerformanceHud
    } else {
        HotkeyAction::None
    }
}

fn gamepad_action_for_button(bindings: GamepadActionBindings, button: Button) -> HotkeyAction {
    let Some(binding) = gamepad_button_binding_from_sdl_button(button) else {
        return HotkeyAction::None;
    };

    gamepad_action_for_binding(bindings, binding)
}

fn gamepad_action_for_binding(
    bindings: GamepadActionBindings,
    binding: GamepadButtonBinding,
) -> HotkeyAction {
    if bindings.save_state == Some(binding) {
        HotkeyAction::SaveState
    } else if bindings.load_state == Some(binding) {
        HotkeyAction::LoadState
    } else if bindings.rewind == Some(binding) {
        HotkeyAction::Rewind
    } else if bindings.fast_forward == Some(binding) {
        HotkeyAction::FastForward
    } else {
        HotkeyAction::None
    }
}

fn gamepad_trigger_event_binding(
    state: &mut GamepadTriggerState,
    axis: Axis,
    value: i16,
) -> Option<(GamepadButtonBinding, bool)> {
    let binding = gamepad_button_binding_from_sdl_axis(axis)?;
    let current = state.pressed_mut(binding)?;
    let next = gamepad_trigger_axis_next_pressed(value, *current);
    if *current == next {
        return None;
    }
    *current = next;
    Some((binding, next))
}

fn apply_gamepad_action_event(
    event: GamepadActionEvent,
    canvas: &mut Canvas<Window>,
    context: &mut FrontendActionContext<'_>,
) -> Result<(), String> {
    if !event.pressed {
        if matches!(event.action, HotkeyAction::Rewind) {
            context.runtime.rewind_gamepad_active = false;
        }
        if matches!(event.action, HotkeyAction::FastForward) {
            context.runtime.fast_forward_gamepad_active = false;
        }
        return Ok(());
    }

    match event.action {
        HotkeyAction::SaveState => {
            match save_machine_state_slot(
                context.session,
                context.machine,
                context.runtime.machine_state_slot,
            ) {
                Ok(path) => eprintln!("info: state saved to {}", path.display()),
                Err(error) => {
                    show_warning_message(Some(canvas.window()), "Save State", &error);
                    eprintln!("warning: {error}");
                }
            }
        }
        HotkeyAction::LoadState => {
            handle_load_machine_state_action(
                context.session,
                context.machine,
                context.runtime,
                context.performance_counter,
                context.frame_pacer,
                canvas,
            )?;
        }
        HotkeyAction::Rewind => {
            context.runtime.rewind_gamepad_active = true;
        }
        HotkeyAction::FastForward => {
            context.runtime.fast_forward_gamepad_active = true;
        }
        HotkeyAction::None
        | HotkeyAction::ManualSave
        | HotkeyAction::SelectStateSlot(_)
        | HotkeyAction::Reset
        | HotkeyAction::ToggleFullscreen
        | HotkeyAction::TogglePerformanceHud => {}
    }

    Ok(())
}

fn desktop_key_from_keycode(keycode: Keycode) -> Option<DesktopKey> {
    match keycode {
        Keycode::Escape => Some(DesktopKey::Escape),
        Keycode::Up => Some(DesktopKey::ArrowUp),
        Keycode::Down => Some(DesktopKey::ArrowDown),
        Keycode::Left => Some(DesktopKey::ArrowLeft),
        Keycode::Right => Some(DesktopKey::ArrowRight),
        Keycode::Tab => Some(DesktopKey::Tab),
        Keycode::Backspace => Some(DesktopKey::Backspace),
        Keycode::Return => Some(DesktopKey::Return),
        Keycode::Space => Some(DesktopKey::Space),
        Keycode::R => Some(DesktopKey::R),
        Keycode::X => Some(DesktopKey::X),
        Keycode::Z => Some(DesktopKey::Z),
        Keycode::_1 => Some(DesktopKey::Digit1),
        Keycode::_2 => Some(DesktopKey::Digit2),
        Keycode::_3 => Some(DesktopKey::Digit3),
        Keycode::_4 => Some(DesktopKey::Digit4),
        Keycode::F1 => Some(DesktopKey::F1),
        Keycode::F2 => Some(DesktopKey::F2),
        Keycode::F3 => Some(DesktopKey::F3),
        Keycode::F4 => Some(DesktopKey::F4),
        Keycode::F5 => Some(DesktopKey::F5),
        Keycode::F6 => Some(DesktopKey::F6),
        Keycode::F7 => Some(DesktopKey::F7),
        Keycode::F8 => Some(DesktopKey::F8),
        Keycode::F9 => Some(DesktopKey::F9),
        Keycode::F10 => Some(DesktopKey::F10),
        Keycode::F11 => Some(DesktopKey::F11),
        Keycode::F12 => Some(DesktopKey::F12),
        Keycode::LShift => Some(DesktopKey::LeftShift),
        Keycode::RShift => Some(DesktopKey::RightShift),
        Keycode::LCtrl => Some(DesktopKey::LeftControl),
        Keycode::RCtrl => Some(DesktopKey::RightControl),
        Keycode::LAlt => Some(DesktopKey::LeftAlt),
        Keycode::RAlt => Some(DesktopKey::RightAlt),
        Keycode::LGui => Some(DesktopKey::LeftGui),
        Keycode::RGui => Some(DesktopKey::RightGui),
        _ => None,
    }
}

fn desktop_modifier_key_from_keycode(keycode: Keycode) -> Option<DesktopKey> {
    match keycode {
        Keycode::LShift => Some(DesktopKey::LeftShift),
        Keycode::RShift => Some(DesktopKey::RightShift),
        Keycode::LCtrl => Some(DesktopKey::LeftControl),
        Keycode::RCtrl => Some(DesktopKey::RightControl),
        Keycode::LAlt => Some(DesktopKey::LeftAlt),
        Keycode::RAlt => Some(DesktopKey::RightAlt),
        Keycode::LGui => Some(DesktopKey::LeftGui),
        Keycode::RGui => Some(DesktopKey::RightGui),
        _ => None,
    }
}

fn desktop_key_from_scancode(scancode: Scancode) -> Option<DesktopKey> {
    match scancode {
        Scancode::Escape => Some(DesktopKey::Escape),
        Scancode::Up => Some(DesktopKey::ArrowUp),
        Scancode::Down => Some(DesktopKey::ArrowDown),
        Scancode::Left => Some(DesktopKey::ArrowLeft),
        Scancode::Right => Some(DesktopKey::ArrowRight),
        Scancode::Tab => Some(DesktopKey::Tab),
        Scancode::Backspace => Some(DesktopKey::Backspace),
        Scancode::Return => Some(DesktopKey::Return),
        Scancode::Space => Some(DesktopKey::Space),
        Scancode::R => Some(DesktopKey::R),
        Scancode::X => Some(DesktopKey::X),
        Scancode::Z => Some(DesktopKey::Z),
        Scancode::_1 => Some(DesktopKey::Digit1),
        Scancode::_2 => Some(DesktopKey::Digit2),
        Scancode::_3 => Some(DesktopKey::Digit3),
        Scancode::_4 => Some(DesktopKey::Digit4),
        Scancode::F1 => Some(DesktopKey::F1),
        Scancode::F2 => Some(DesktopKey::F2),
        Scancode::F3 => Some(DesktopKey::F3),
        Scancode::F4 => Some(DesktopKey::F4),
        Scancode::F5 => Some(DesktopKey::F5),
        Scancode::F6 => Some(DesktopKey::F6),
        Scancode::F7 => Some(DesktopKey::F7),
        Scancode::F8 => Some(DesktopKey::F8),
        Scancode::F9 => Some(DesktopKey::F9),
        Scancode::F10 => Some(DesktopKey::F10),
        Scancode::F11 => Some(DesktopKey::F11),
        Scancode::F12 => Some(DesktopKey::F12),
        Scancode::LShift => Some(DesktopKey::LeftShift),
        Scancode::RShift => Some(DesktopKey::RightShift),
        Scancode::LCtrl => Some(DesktopKey::LeftControl),
        Scancode::RCtrl => Some(DesktopKey::RightControl),
        Scancode::LAlt => Some(DesktopKey::LeftAlt),
        Scancode::RAlt => Some(DesktopKey::RightAlt),
        Scancode::LGui => Some(DesktopKey::LeftGui),
        Scancode::RGui => Some(DesktopKey::RightGui),
        _ => None,
    }
}

fn desktop_key_from_key_event(
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
) -> Option<DesktopKey> {
    if let Some(modifier_key) = keycode.and_then(desktop_modifier_key_from_keycode) {
        return Some(modifier_key);
    }

    match scancode {
        Some(scancode) => desktop_key_from_scancode(scancode),
        None => keycode.and_then(desktop_key_from_keycode),
    }
}

#[cfg(test)]
fn assignable_key_for_binding_target_from_keycode(
    keycode: Keycode,
    target: KeyboardBindingTarget,
) -> Option<DesktopKey> {
    let key = desktop_key_from_keycode(keycode)?;
    assignable_key_for_binding_target(key, target)
}

fn assignable_key_for_binding_target_from_key_event(
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
    target: KeyboardBindingTarget,
) -> Option<DesktopKey> {
    let key = desktop_key_from_key_event(keycode, scancode)?;
    assignable_key_for_binding_target(key, target)
}

fn assignable_key_for_binding_target(
    key: DesktopKey,
    target: KeyboardBindingTarget,
) -> Option<DesktopKey> {
    match target {
        KeyboardBindingTarget::Pause
        | KeyboardBindingTarget::SaveState
        | KeyboardBindingTarget::LoadState
        | KeyboardBindingTarget::StateSlot1
        | KeyboardBindingTarget::StateSlot2
        | KeyboardBindingTarget::StateSlot3
        | KeyboardBindingTarget::StateSlot4
        | KeyboardBindingTarget::Reset
        | KeyboardBindingTarget::Rewind
        | KeyboardBindingTarget::FastForward
        | KeyboardBindingTarget::ToggleFullscreen
        | KeyboardBindingTarget::TogglePerformanceHud
        | KeyboardBindingTarget::SaveBattery => is_hotkey_assignable_key(key).then_some(key),
        KeyboardBindingTarget::Up
        | KeyboardBindingTarget::Down
        | KeyboardBindingTarget::Left
        | KeyboardBindingTarget::Right
        | KeyboardBindingTarget::A
        | KeyboardBindingTarget::B
        | KeyboardBindingTarget::Select
        | KeyboardBindingTarget::Start => is_joypad_assignable_key(key).then_some(key),
    }
}

#[cfg(test)]
fn assignable_menu_key_for_binding_target_from_keycode(
    keycode: Keycode,
    target: KeyboardMenuBindingTarget,
) -> Option<DesktopKey> {
    let key = desktop_key_from_keycode(keycode)?;
    assignable_menu_key_for_binding_target(key, target)
}

fn assignable_menu_key_for_binding_target_from_key_event(
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
    target: KeyboardMenuBindingTarget,
) -> Option<DesktopKey> {
    let key = desktop_key_from_key_event(keycode, scancode)?;
    assignable_menu_key_for_binding_target(key, target)
}

fn assignable_menu_key_for_binding_target(
    key: DesktopKey,
    target: KeyboardMenuBindingTarget,
) -> Option<DesktopKey> {
    match target {
        KeyboardMenuBindingTarget::Cancel => Some(key),
        KeyboardMenuBindingTarget::Up
        | KeyboardMenuBindingTarget::Down
        | KeyboardMenuBindingTarget::Confirm => (!matches!(key, DesktopKey::Escape)).then_some(key),
    }
}

fn is_joypad_assignable_key(key: DesktopKey) -> bool {
    !matches!(
        key,
        DesktopKey::Escape
            | DesktopKey::Digit1
            | DesktopKey::Digit2
            | DesktopKey::Digit3
            | DesktopKey::Digit4
            | DesktopKey::F1
            | DesktopKey::F2
            | DesktopKey::F3
            | DesktopKey::F4
            | DesktopKey::F5
            | DesktopKey::F6
            | DesktopKey::F7
            | DesktopKey::F8
            | DesktopKey::F9
            | DesktopKey::F10
            | DesktopKey::F11
            | DesktopKey::F12
    )
}

fn is_hotkey_assignable_key(key: DesktopKey) -> bool {
    !matches!(key, DesktopKey::Escape)
}

#[cfg(test)]
fn key_matches(binding: DesktopKey, keycode: Keycode) -> bool {
    desktop_key_from_keycode(keycode) == Some(binding)
}

fn key_event_matches(
    binding: DesktopKey,
    keycode: Option<Keycode>,
    scancode: Option<Scancode>,
) -> bool {
    desktop_key_from_key_event(keycode, scancode) == Some(binding)
}

fn startup_mode_name(startup_mode: StartupMode) -> &'static str {
    match startup_mode {
        StartupMode::SkipBoot => "skip-boot",
        StartupMode::CustomBoot => "custom-boot",
        StartupMode::RealBoot => "real-boot",
    }
}

fn execution_mode_name(execution_mode: ExecutionMode) -> &'static str {
    match execution_mode {
        ExecutionMode::Strict => "strict",
        ExecutionMode::Permissive => "permissive",
        ExecutionMode::Experimental => "experimental",
    }
}

fn display_palette_for_desktop_palette(display_palette: DesktopDisplayPalette) -> DisplayPalette {
    match display_palette {
        DesktopDisplayPalette::Grey => DMG_GREY_DISPLAY_PALETTE,
        DesktopDisplayPalette::GameBoy => DMG_DISPLAY_PALETTE,
        DesktopDisplayPalette::Pocket => MGB_DISPLAY_PALETTE,
        DesktopDisplayPalette::Light => GBL_DISPLAY_PALETTE,
    }
}

