    #[test]
    fn step_until_next_frame_returns_profile_requests_for_sampled_frames() {
        let _guard = crate::lock_sdl_test();
        let mut harness = FrontendHarness::new("step-profile", true, true, false);
        harness.performance_counter = super::PerformanceCounter::new_with_emulation_profile_mode(
            "gb-desktop | step-profile".to_string(),
            super::EmulationProfileMode::SampledSummary {
                sample_every_frames: 2,
                detail: super::EmulationProfileDetail::CoreOnly,
            },
        );
        harness.performance_counter.presented_frames_total = 1;
        let FrontendHarness {
            event_pump,
            canvas,
            session,
            machine,
            runtime,
            settings_store,
            performance_counter,
            frame_pacer,
            ..
        } = &mut harness;
        let mut context = super::FrontendActionContext {
            session,
            machine,
            runtime,
            performance_counter,
            frame_pacer,
            settings_store,
        };
        let result = super::step_until_next_frame(event_pump, canvas, &mut context)
            .expect("sampled stepping should succeed");
        assert_eq!(result.signal, super::LoopSignal::Continue);
        let request = result
            .emulation_profile_request
            .expect("sampled frames should snapshot a profile request");
        assert_eq!(result.frame_loop_telemetry.start_ly, 0);
        assert_eq!(result.frame_loop_telemetry.start_dot, 0);
        assert_eq!(result.frame_loop_telemetry.end_ly, 0);
        assert_eq!(result.frame_loop_telemetry.end_dot, 0);
        assert!(result.frame_loop_telemetry.stepped_t_cycles > 0);
        assert_eq!(result.frame_loop_telemetry.frame_origin_crossings, 1);
        assert_eq!(request.detail, super::EmulationProfileDetail::CoreOnly);
        assert!(request.breakdown.host_event_poll_duration <= Duration::from_millis(50));
        assert!(request.breakdown.host_audio_submit_duration <= Duration::from_millis(50));
    }

    #[test]
    fn trace_capture_t_cycles_parser_uses_default_and_rejects_zero() {
        assert_eq!(parse_trace_capture_t_cycles(None), Ok(8_192));
        assert_eq!(
            parse_trace_capture_t_cycles(Some(OsStr::new("4096"))),
            Ok(4_096)
        );
        assert!(
            parse_trace_capture_t_cycles(Some(OsStr::new("0")))
                .expect_err("zero trace window should be rejected")
                .contains("must be greater than zero")
        );
    }

    #[test]
    fn watch_trace_parsers_accept_hex_addresses_and_reject_empty_or_zero_counts() {
        assert_eq!(
            parse_watch_trace_addresses(Some(OsStr::new("FF00, 0xFF82;C400"))),
            Ok(BTreeSet::from([0xFF00, 0xFF82, 0xC400]))
        );
        assert!(
            parse_watch_trace_addresses(Some(OsStr::new(" , ; ")))
                .expect_err("empty watch-address list should be rejected")
                .contains("must list one or more watched addresses")
        );
        assert_eq!(parse_watch_trace_event_count(None), Ok(4_096));
        assert_eq!(
            parse_watch_trace_event_count(Some(OsStr::new("1024"))),
            Ok(1_024)
        );
        assert!(
            parse_watch_trace_event_count(Some(OsStr::new("0")))
                .expect_err("zero watch trace event count should be rejected")
                .contains("must be greater than zero")
        );
    }

    #[test]
    fn pc_watch_trace_parsers_accept_ranges_and_reject_empty_or_zero_counts() {
        assert_eq!(
            parse_pc_watch_trace_ranges(Some(OsStr::new("03C0-03EF, 0x05FD..=0x062F, 4C00"))),
            Ok(vec![
                super::PcWatchRange {
                    start: 0x03C0,
                    end: 0x03EF,
                },
                super::PcWatchRange {
                    start: 0x05FD,
                    end: 0x062F,
                },
                super::PcWatchRange {
                    start: 0x4C00,
                    end: 0x4C00,
                },
            ])
        );
        assert!(
            parse_pc_watch_trace_ranges(Some(OsStr::new(" , ; ")))
                .expect_err("empty PC watch-range list should be rejected")
                .contains("must list one or more watched PC ranges")
        );
        assert!(
            parse_pc_watch_trace_ranges(Some(OsStr::new("062F-05FD")))
                .expect_err("descending PC watch range should be rejected")
                .contains("range end")
        );
        assert_eq!(parse_pc_watch_trace_event_count(None), Ok(4_096));
        assert_eq!(
            parse_pc_watch_trace_event_count(Some(OsStr::new("2048"))),
            Ok(2_048)
        );
        assert!(
            parse_pc_watch_trace_event_count(Some(OsStr::new("0")))
                .expect_err("zero PC watch trace event count should be rejected")
                .contains("must be greater than zero")
        );
    }

