    #[test]
    fn framebuffer_render_input_uses_the_active_desktop_display_palette() {
        let machine = super::DesktopEmulationSession::new_single(Machine::new_summary(
            MachineConfig::new(ConsoleModel::GameBoy).with_startup_mode(StartupMode::SkipBoot),
        ));
        let video_options = gb_desktop::VideoOptions {
            display_palette: DesktopDisplayPalette::Light,
            ..gb_desktop::VideoOptions::default()
        };

        let render_input = super::framebuffer_render_input_for_session(
            &machine,
            super::framebuffer_dimensions_for_session(&machine, &video_options, true),
            &video_options,
            true,
        );

        let panel = render_input.panels[0]
            .as_ref()
            .expect("primary panel should be populated");
        assert_eq!(panel.display_palette, super::GBL_DISPLAY_PALETTE);
        assert!(render_input.panels[1..].iter().all(Option::is_none));
    }

    #[test]
    fn framebuffer_render_input_uses_sgb_host_frame_dimensions_and_rgb555_output() {
        let machine = super::DesktopEmulationSession::new_single(Machine::new_summary(
            MachineConfig::new(ConsoleModel::GameBoy)
                .with_startup_mode(StartupMode::SkipBoot)
                .with_sgb_profile(SgbHostProfile::SgbNtsc),
        ));
        let video_options = gb_desktop::VideoOptions::default();
        let dimensions = super::framebuffer_dimensions_for_session(&machine, &video_options, true);

        let render_input =
            super::framebuffer_render_input_for_session(&machine, dimensions, &video_options, true);

        assert_eq!(
            dimensions,
            super::FramebufferDimensions {
                width: super::SGB_HOST_FRAMEBUFFER_WIDTH,
                height: super::SGB_HOST_FRAMEBUFFER_HEIGHT,
            }
        );
        let panel = render_input.panels[0]
            .as_ref()
            .expect("SGB panel should be populated");
        assert_eq!(panel.dimensions, dimensions);
        assert_eq!(
            panel
                .sgb_framebuffer_rgb555
                .as_ref()
                .expect("SGB panel should carry host RGB555 output")
                .len(),
            (super::SGB_HOST_FRAMEBUFFER_WIDTH * super::SGB_HOST_FRAMEBUFFER_HEIGHT) as usize
        );

        let hidden_border_options = gb_desktop::VideoOptions {
            show_sgb_border: false,
            ..gb_desktop::VideoOptions::default()
        };
        let hidden_dimensions =
            super::framebuffer_dimensions_for_session(&machine, &hidden_border_options, true);
        let hidden_render_input = super::framebuffer_render_input_for_session(
            &machine,
            hidden_dimensions,
            &hidden_border_options,
            true,
        );
        assert_eq!(
            hidden_dimensions,
            super::FramebufferDimensions {
                width: super::FRAMEBUFFER_WIDTH,
                height: super::FRAMEBUFFER_HEIGHT,
            }
        );
        let hidden_panel = hidden_render_input.panels[0]
            .as_ref()
            .expect("hidden-border SGB panel should be populated");
        assert_eq!(hidden_panel.dimensions, hidden_dimensions);
        assert_eq!(
            hidden_panel
                .sgb_framebuffer_rgb555
                .as_ref()
                .expect("hidden-border SGB panel should carry LCD RGB555 output")
                .len(),
            (super::FRAMEBUFFER_WIDTH * super::FRAMEBUFFER_HEIGHT) as usize
        );
    }

    #[test]
    fn launcher_sgb_profile_uses_handheld_dimensions_until_a_rom_is_loaded() {
        let machine = super::DesktopEmulationSession::new_single(Machine::new_summary(
            MachineConfig::new(ConsoleModel::GameBoy)
                .with_startup_mode(StartupMode::SkipBoot)
                .with_sgb_profile(SgbHostProfile::Sgb2Ntsc),
        ));
        for show_sgb_border in [true, false] {
            let video_options = gb_desktop::VideoOptions {
                show_sgb_border,
                ..gb_desktop::VideoOptions::default()
            };
            let dimensions =
                super::framebuffer_dimensions_for_session(&machine, &video_options, false);
            let render_input = super::framebuffer_render_input_for_session(
                &machine,
                dimensions,
                &video_options,
                false,
            );

            assert_eq!(
                dimensions,
                super::FramebufferDimensions {
                    width: super::FRAMEBUFFER_WIDTH,
                    height: super::FRAMEBUFFER_HEIGHT,
                }
            );
            let panel = render_input.panels[0]
                .as_ref()
                .expect("launcher panel should be populated");
            assert_eq!(panel.dimensions, dimensions);
            assert!(
                panel.sgb_framebuffer_rgb555.is_none(),
                "launcher presentation must not allocate an SGB host frame before a ROM is loaded"
            );
        }
    }

    #[test]
    fn cgb_framebuffer_rendering_uses_rgb555_without_desktop_display_palette() {
        let panel_len = (super::FRAMEBUFFER_WIDTH * super::FRAMEBUFFER_HEIGHT) as usize;
        let framebuffer = vec![0_u8; panel_len];
        let layer_sources = vec![PpuFramebufferLayerSource::Background; panel_len];
        let mut cgb_framebuffer_rgb555 = vec![0x7FFF_u16; panel_len];
        cgb_framebuffer_rgb555[0] = 0x001F;
        cgb_framebuffer_rgb555[1] = 0x03E0;
        cgb_framebuffer_rgb555[2] = 0x7C00;
        let mut rgb_frame =
            vec![0_u8; super::FRAMEBUFFER_HEIGHT as usize * super::FRAMEBUFFER_PITCH_BYTES];

        super::write_framebuffer_region(
            &mut rgb_frame,
            super::FramebufferDimensions {
                width: super::FRAMEBUFFER_WIDTH,
                height: super::FRAMEBUFFER_HEIGHT,
            },
            0,
            0,
            super::FramebufferPanelInput {
                dimensions: super::FramebufferDimensions {
                    width: super::FRAMEBUFFER_WIDTH,
                    height: super::FRAMEBUFFER_HEIGHT,
                },
                framebuffer: &framebuffer,
                framebuffer_layer_sources: &layer_sources,
                bgwin_framebuffer: &framebuffer,
                backdrop_framebuffer: &framebuffer,
                bgwin_framebuffer_layer_sources: &layer_sources,
                display_palette: super::GBL_DISPLAY_PALETTE,
                cgb_framebuffer_rgb555: Some(&cgb_framebuffer_rgb555),
                sgb_framebuffer_rgb555: None,
            },
            &gb_desktop::VideoOptions {
                display_palette: DesktopDisplayPalette::Light,
                ..gb_desktop::VideoOptions::default()
            },
        );

        assert_eq!(
            &rgb_frame[..9],
            &[0xFF, 0x00, 0x00, 0x00, 0xFF, 0x00, 0x00, 0x00, 0xFF]
        );
    }

    #[test]
    fn frame_blending_state_keeps_the_first_frame_raw_and_simple_blends_gamma_correctly() {
        let dimensions = super::FramebufferDimensions {
            width: 1,
            height: 1,
        };
        let mut state = super::FrameBlendingState::default();
        let mut first_frame = vec![255_u8; 3];

        state.apply(&mut first_frame, dimensions, DesktopFrameBlendingMode::On);

        assert_eq!(first_frame, vec![255_u8; 3]);
        assert_eq!(state.previous_rgb_frame, vec![255_u8; 3]);
        assert!(state.has_previous_frame);

        let mut second_frame = vec![0_u8; 3];
        state.apply(&mut second_frame, dimensions, DesktopFrameBlendingMode::On);

        assert_eq!(second_frame, vec![186_u8; 3]);
        assert_eq!(state.previous_rgb_frame, vec![0_u8; 3]);
    }

    #[test]
    fn frame_blending_uses_the_same_half_weight_for_every_line() {
        let dimensions = super::FramebufferDimensions {
            width: 1,
            height: 2,
        };
        let current_frame = vec![0_u8; 6];
        let previous_frame = vec![255_u8; 6];
        let mut target = current_frame.clone();

        super::blend_rgb24_frames(
            &mut target,
            &current_frame,
            &previous_frame,
            dimensions,
            DesktopFrameBlendingMode::On,
        );

        assert_eq!(&target[0..3], &[186_u8; 3]);
        assert_eq!(&target[3..6], &[186_u8; 3]);
    }

    #[test]
    fn frame_blending_state_clears_history_for_mode_and_dimension_changes() {
        let one_pixel = super::FramebufferDimensions {
            width: 1,
            height: 1,
        };
        let two_pixels = super::FramebufferDimensions {
            width: 2,
            height: 1,
        };
        let mut state = super::FrameBlendingState::default();
        let mut first_frame = vec![255_u8; 3];
        let mut second_frame = vec![0_u8; 3];

        state.apply(&mut first_frame, one_pixel, DesktopFrameBlendingMode::On);
        state.apply(&mut second_frame, one_pixel, DesktopFrameBlendingMode::On);
        assert_eq!(second_frame, vec![186_u8; 3]);

        let mut resized_frame = vec![64_u8; 6];
        state.apply(&mut resized_frame, two_pixels, DesktopFrameBlendingMode::On);
        assert_eq!(resized_frame, vec![64_u8; 6]);
        assert_eq!(state.dimensions, Some(two_pixels));
        assert_eq!(state.previous_rgb_frame, vec![64_u8; 6]);
        assert!(state.has_previous_frame);

        let mut disabled_frame = vec![32_u8; 6];
        state.apply(
            &mut disabled_frame,
            two_pixels,
            DesktopFrameBlendingMode::Off,
        );
        assert_eq!(disabled_frame, vec![32_u8; 6]);
        assert_eq!(state.mode, DesktopFrameBlendingMode::Off);
        assert!(state.previous_rgb_frame.is_empty());
        assert!(!state.has_previous_frame);
    }

    #[test]
    fn benchmark_helpers_apply_cases_and_write_artifacts() {
        let root = temp_test_root("benchmark-artifact-helpers");
        let rom_path = root.join("bench.gb");
        let rom_bytes = build_test_rom(32 * 1024, 0x00, 0x00, 0x00);
        fs::write(&rom_path, &rom_bytes).expect("benchmark ROM should be writable");

        let mut options = DesktopRunOptions {
            rom_path: None,
            linked_peer_rom_path: None,
            benchmark_path: None,
            exit_after_frames: None,
            config: DesktopConfig::default(),
            audio_recording: None,
            test_runner: true,
        };
        options.config.video.display_palette = DesktopDisplayPalette::Light;
        let dmg_case = BenchmarkCase {
            source_path: root.join("test/bench.toml"),
            id: "bench".to_string(),
            run_id: Some("dmg".to_string()),
            run_label: Some("DMG run".to_string()),
            artifact_id: "bench-dmg".to_string(),
            rom: rom_path.clone(),
            model: BenchmarkModel::Dmg,
            startup: BenchmarkStartup::CustomBoot,
            mode: BenchmarkMode::Permissive,
            palette: Some(BenchmarkPalette::Grey),
            duration_seconds: 2,
            screenshot: true,
            stats: true,
            stimuli: Vec::new(),
        };
        super::apply_benchmark_case_to_desktop_options(&mut options, &dmg_case);
        assert_eq!(options.rom_path, Some(rom_path.clone()));
        assert_eq!(options.exit_after_frames, Some(120));
        assert_eq!(
            options.config.launch.console_model,
            DesktopConsoleModel::GameBoy
        );
        assert_eq!(options.config.launch.revision, HardwareRevision::DmgCpuC);
        assert_eq!(options.config.launch.startup_mode, StartupMode::CustomBoot);
        assert_eq!(
            options.config.launch.execution_mode,
            ExecutionMode::Permissive
        );
        assert_eq!(
            options.config.video.display_palette,
            DesktopDisplayPalette::Grey
        );
        assert!(!options.config.video.show_sgb_border);

        assert_eq!(
            super::desktop_model_from_benchmark(BenchmarkModel::Dmg),
            DesktopConsoleModel::GameBoy
        );
        assert_eq!(
            super::desktop_model_from_benchmark(BenchmarkModel::Mgb),
            DesktopConsoleModel::GameBoyPocket
        );
        assert_eq!(
            super::desktop_model_from_benchmark(BenchmarkModel::Lgb),
            DesktopConsoleModel::GameBoyLight
        );
        assert_eq!(
            super::desktop_model_from_benchmark(BenchmarkModel::Cgb),
            DesktopConsoleModel::GameBoyColor
        );
        assert_eq!(
            super::startup_mode_from_benchmark(BenchmarkStartup::SkipBoot),
            StartupMode::SkipBoot
        );
        assert_eq!(
            super::startup_mode_from_benchmark(BenchmarkStartup::CustomBoot),
            StartupMode::CustomBoot
        );
        assert_eq!(
            super::startup_mode_from_benchmark(BenchmarkStartup::RealBoot),
            StartupMode::RealBoot
        );
        assert_eq!(
            super::execution_mode_from_benchmark(BenchmarkMode::Strict),
            ExecutionMode::Strict
        );
        assert_eq!(
            super::execution_mode_from_benchmark(BenchmarkMode::Permissive),
            ExecutionMode::Permissive
        );
        assert_eq!(
            super::execution_mode_from_benchmark(BenchmarkMode::Experimental),
            ExecutionMode::Experimental
        );
        assert_eq!(
            super::desktop_display_palette_from_benchmark(BenchmarkPalette::Grey),
            DesktopDisplayPalette::Grey
        );

        let mut cgb_options = options.clone();
        cgb_options.config.video.display_palette = DesktopDisplayPalette::Light;
        let mut cgb_case = dmg_case.clone();
        cgb_case.model = BenchmarkModel::Cgb;
        cgb_case.startup = BenchmarkStartup::RealBoot;
        cgb_case.mode = BenchmarkMode::Experimental;
        super::apply_benchmark_case_to_desktop_options(&mut cgb_options, &cgb_case);
        assert_eq!(
            cgb_options.config.launch.console_model,
            DesktopConsoleModel::GameBoyColor
        );
        assert_eq!(
            cgb_options.config.launch.revision,
            HardwareRevision::CpuCgbE
        );
        assert_eq!(
            cgb_options.config.video.display_palette,
            DesktopDisplayPalette::Light
        );
        assert_eq!(
            cgb_options.config.launch.execution_mode,
            ExecutionMode::Permissive
        );
        assert!(!cgb_options.config.video.show_sgb_border);

        let machine = super::DesktopEmulationSession::new_single(
            super::load_machine_for_rom(&options.config, &root, &rom_bytes)
                .expect("benchmark machine should load")
                .machine,
        );
        let session = super::DesktopSession {
            config: options.config.clone(),
            test_runner: true,
            benchmark: Some(super::DesktopBenchmarkRun {
                case: dmg_case.clone(),
                stimuli: BenchmarkStimulusRuntime::new(Vec::new()),
                started_at: Instant::now(),
                started_t_cycle: 0,
            }),
            current_dir: root.clone(),
            loaded_rom: Some(super::LoadedRom {
                path: rom_path,
                bytes: rom_bytes,
            }),
            linked_secondary_rom: None,
            dmg07_player_count: None,
            cgb_infrared_link_active: false,
            pokemon_pikachu_color_active: false,
            pokemon_pikachu_color_gift: PokemonPikachuColorGift::default(),
            pokemon_mystery_gift_active: false,
            pokemon_mystery_gift_kind: PokemonMysteryGiftKind::default(),
            pokemon_mystery_gift_code: PokemonMysteryGiftCode::default(),
            last_open_directory: Some(root.clone()),
            recent_roms: Vec::new(),
            pocket_camera_frame: None,
            external_port_selection: DesktopExternalPortSelection::None,
        };
        let performance_counter = super::PerformanceCounter::new_with_emulation_profile_mode(
            "benchmark".to_string(),
            super::EmulationProfileMode::Disabled,
        );
        super::write_benchmark_artifacts_for_session(
            &session,
            &machine,
            &session.config.video,
            &performance_counter,
        )
        .expect("benchmark artifacts should be written");
        assert!(root.join("gb-desktop/bench-dmg.png").exists());
        let stats = fs::read_to_string(root.join("gb-desktop/bench-dmg-stats.toml"))
            .expect("benchmark stats should be written");
        assert!(stats.contains("artifact_id = \"bench-dmg\""));
        assert!(stats.contains("run_label = \"DMG run\""));

        let no_benchmark_session = super::DesktopSession {
            benchmark: None,
            ..session
        };
        super::write_benchmark_artifacts_for_session(
            &no_benchmark_session,
            &machine,
            &no_benchmark_session.config.video,
            &performance_counter,
        )
        .expect("missing benchmark context should be a no-op");

        let nested_text_path = root.join("nested/artifact.txt");
        super::write_text_file_with_parent(&nested_text_path, "ok")
            .expect("text artifacts should create parent directories");
        assert_eq!(
            fs::read_to_string(nested_text_path).expect("text artifact should be readable"),
            "ok"
        );

        let suite_error = super::run_desktop_with_startup_fallback_persistence(
            DesktopRunOptions {
                benchmark_path: Some(root.join("missing-benchmark.toml")),
                ..options
            },
            DesktopSettingsStore::new_for_tests(root.join("missing-settings.toml")),
            false,
        )
        .expect_err("missing benchmark suites should fail before SDL startup");
        assert!(suite_error.contains("missing-benchmark.toml"));
    }

