    #[test]
    fn frontend_harness_covers_event_loop_frame_and_render_helpers() {
        let _guard = crate::lock_sdl_test();
        let mut harness = FrontendHarness::new("runtime", true, true, true);
        let relative_rom = PathBuf::from("runtime.gb");
        let relative_rom_path = harness.root.join(&relative_rom);
        fs::write(
            &relative_rom_path,
            build_test_rom(32 * 1024, 0x00, 0x00, 0x00),
        )
        .expect("runtime ROM should be writable");

        let loaded = super::load_initial_rom(
            &DesktopRunOptions {
                rom_path: Some(relative_rom.clone()),
                linked_peer_rom_path: None,
                benchmark_path: None,
                exit_after_frames: None,
                config: DesktopConfig::default(),
                audio_recording: None,
                test_runner: false,
            },
            &harness.root,
        )
        .expect("relative ROM path should load")
        .expect("relative ROM should exist");
        assert_eq!(loaded.path, relative_rom_path);
        assert!(
            super::load_initial_rom(
                &DesktopRunOptions {
                    rom_path: None,
                    linked_peer_rom_path: None,
                    benchmark_path: None,
                    exit_after_frames: None,
                    config: DesktopConfig::default(),
                    audio_recording: None,
                    test_runner: false,
                },
                &harness.root,
            )
            .expect("missing ROM path should be allowed")
            .is_none()
        );
        let linked_loaded = super::load_initial_linked_secondary_rom(
            &DesktopRunOptions {
                rom_path: Some(relative_rom.clone()),
                linked_peer_rom_path: Some(relative_rom.clone()),
                benchmark_path: None,
                exit_after_frames: Some(8),
                config: DesktopConfig::default(),
                audio_recording: None,
                test_runner: false,
            },
            &harness.root,
        )
        .expect("relative linked peer path should load")
        .expect("relative linked peer should exist");
        assert_eq!(linked_loaded.path, relative_rom_path);
        assert!(super::should_exit_after_presented_frames(Some(4), 4));
        assert!(!super::should_exit_after_presented_frames(Some(5), 4));
        assert!(!super::should_exit_after_presented_frames(None, 4));

        let mut reloaded_machine = super::load_machine_for_rom(
            &harness.session.config,
            &harness.session.current_dir,
            harness.session.rom_bytes().expect("loaded ROM bytes"),
        )
        .expect("machine should reload from ROM bytes")
        .machine;
        assert!(
            super::open_save_session_for_session(&harness.session, &mut reloaded_machine)
                .expect("save session should open for the loaded ROM")
                .is_none()
        );

        super::run_from_cli(["--help"]).expect("help path should succeed");
        let expected_toggled_device = harness
            .runtime
            .gamepad_manager
            .as_ref()
            .and_then(super::GamepadManager::active_gamepad_identity)
            .unwrap_or_default();
        assert_eq!(
            super::toggled_preferred_gamepad_device(
                harness
                    .runtime
                    .gamepad_manager
                    .as_ref()
                    .expect("runtime test should have a gamepad manager")
            ),
            expected_toggled_device
        );
        if !expected_toggled_device.is_configured() {
            assert_eq!(
                harness
                    .runtime
                    .gamepad_manager
                    .as_ref()
                    .expect("runtime test should have a gamepad manager")
                    .preferred_device(),
                &gb_desktop::PreferredGamepadIdentity {
                    path: None,
                    name: Some("Saved Pad".to_string()),
                }
            );
        } else {
            harness
                .runtime
                .gamepad_manager
                .as_mut()
                .expect("runtime test should have a gamepad manager")
                .set_preferred_device(
                    expected_toggled_device.clone(),
                    harness
                        .runtime
                        .player_inputs
                        .input_mut(super::PlayerSlot::P1),
                    harness
                        .machine
                        .machine_for_player_slot_mut(super::PlayerSlot::P1)
                        .expect("P1 should always map to an active desktop machine"),
                );
            assert_eq!(
                super::toggled_preferred_gamepad_device(
                    harness
                        .runtime
                        .gamepad_manager
                        .as_ref()
                        .expect("runtime test should have a gamepad manager")
                ),
                gb_desktop::PreferredGamepadIdentity::default()
            );
        }

        harness.push_key(Keycode::LAlt, true);
        assert!(matches!(
            harness
                .process_events()
                .expect("keyboard press should process"),
            super::LoopSignal::Continue
        ));
        harness.machine.step_t_cycle();
        assert_ne!(harness.machine.joypad().snapshot().pressed_mask, 0);
        harness.push_key(Keycode::LAlt, false);
        harness
            .process_events()
            .expect("keyboard release should process");
        harness.machine.step_t_cycle();
        assert_eq!(harness.machine.joypad().snapshot().pressed_mask, 0);

        harness.push_key(Keycode::Escape, true);
        harness.process_events().expect("menu open should process");
        assert!(harness.runtime.menu_state.is_open());
        harness.push_key(Keycode::Escape, true);
        harness.process_events().expect("menu close should process");
        assert!(!harness.runtime.menu_state.is_open());

        assert!(matches!(
            harness
                .step_until_next_frame()
                .expect("frame stepping should complete"),
            super::LoopSignal::Continue
        ));

        super::apply_window_scale(harness.canvas.window_mut(), 3)
            .expect("window scale should apply");
        super::set_fullscreen_state(harness.canvas.window_mut(), false)
            .expect("setting the existing fullscreen state should be a no-op");
        super::reset_machine(
            harness.canvas.window(),
            &mut harness.session,
            &mut harness.machine,
            &mut harness.runtime,
            &mut harness.settings_store,
        )
        .expect("machine reset should succeed");

        let texture_creator = harness.canvas.texture_creator();
        let mut texture = texture_creator
            .create_texture_streaming(
                sdl3::pixels::PixelFormat::RGB24,
                super::FRAMEBUFFER_WIDTH,
                super::FRAMEBUFFER_HEIGHT,
            )
            .expect("runtime texture should be creatable");
        let mut rgb_frame =
            vec![0_u8; super::FRAMEBUFFER_HEIGHT as usize * super::FRAMEBUFFER_PITCH_BYTES];
        let menu_presentation = super::current_menu_presentation(
            harness.canvas.window(),
            &harness.runtime,
            &harness.machine,
            &harness.session,
        );
        harness.runtime.menu_state.open(menu_presentation);
        let open_menu_presentation = super::current_menu_presentation(
            harness.canvas.window(),
            &harness.runtime,
            &harness.machine,
            &harness.session,
        );
        let _ = super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut rgb_frame,
            super::FramebufferRenderInput {
                dimensions: super::FramebufferDimensions {
                    width: super::FRAMEBUFFER_WIDTH,
                    height: super::FRAMEBUFFER_HEIGHT,
                },
                panels: [
                    Some(super::FramebufferPanelInput {
                        dimensions: super::FramebufferDimensions {
                            width: super::FRAMEBUFFER_WIDTH,
                            height: super::FRAMEBUFFER_HEIGHT,
                        },
                        framebuffer: harness.machine.ppu().framebuffer(),
                        framebuffer_layer_sources: harness
                            .machine
                            .ppu()
                            .framebuffer_layer_sources(),
                        bgwin_framebuffer: harness.machine.ppu().framebuffer_bgwin_panel_shades(),
                        backdrop_framebuffer: harness
                            .machine
                            .ppu()
                            .framebuffer_backdrop_panel_shades(),
                        bgwin_framebuffer_layer_sources: harness
                            .machine
                            .ppu()
                            .framebuffer_bgwin_layer_sources(),
                        display_palette: super::DMG_DISPLAY_PALETTE,
                        cgb_framebuffer_rgb555: None,
                        sgb_framebuffer_rgb555: None,
                    }),
                    None,
                    None,
                    None,
                ],
            },
            &harness.runtime.video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: Some((&harness.runtime.menu_state, open_menu_presentation)),
                hud: super::RenderHudInput::default(),
            },
        )
        .expect("overlay frame should render");
        assert!(rgb_frame.iter().any(|byte| *byte != 0));

        harness.runtime.menu_state.close();
        harness.runtime.video_options.show_performance_hud = true;
        let _ = super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut rgb_frame,
            super::FramebufferRenderInput {
                dimensions: super::FramebufferDimensions {
                    width: super::FRAMEBUFFER_WIDTH,
                    height: super::FRAMEBUFFER_HEIGHT,
                },
                panels: [
                    Some(super::FramebufferPanelInput {
                        dimensions: super::FramebufferDimensions {
                            width: super::FRAMEBUFFER_WIDTH,
                            height: super::FRAMEBUFFER_HEIGHT,
                        },
                        framebuffer: harness.machine.ppu().framebuffer(),
                        framebuffer_layer_sources: harness
                            .machine
                            .ppu()
                            .framebuffer_layer_sources(),
                        bgwin_framebuffer: harness.machine.ppu().framebuffer_bgwin_panel_shades(),
                        backdrop_framebuffer: harness
                            .machine
                            .ppu()
                            .framebuffer_backdrop_panel_shades(),
                        bgwin_framebuffer_layer_sources: harness
                            .machine
                            .ppu()
                            .framebuffer_bgwin_layer_sources(),
                        display_palette: super::DMG_DISPLAY_PALETTE,
                        cgb_framebuffer_rgb555: None,
                        sgb_framebuffer_rgb555: None,
                    }),
                    None,
                    None,
                    None,
                ],
            },
            &harness.runtime.video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: None,
                hud: super::RenderHudInput {
                    performance: Some(PerformanceHudSnapshot {
                        fps: 59.7,
                        speed_percent: 100.0,
                        frame_time_ms: 16.7,
                        emulation_time_ms: 10.0,
                        render_time_ms: 2.0,
                        pacing_time_ms: 4.0,
                        audio_queue_ms: Some(12.5),
                        rewind: RewindHudSnapshot::default(),
                    }),
                    cgb_ir: None,
                    rewind_indicator: false,
                    fast_forward_indicator: false,
                },
            },
        )
        .expect("HUD frame should render");
        assert!(rgb_frame.iter().any(|byte| *byte != 0));
    }

    #[test]
    fn render_frame_blends_the_base_frame_before_menu_and_hud_overlays() {
        let _guard = crate::lock_sdl_test();
        let mut harness = FrontendHarness::new("frame-blending-render", true, false, false);
        let texture_creator = harness.canvas.texture_creator();
        let mut texture = texture_creator
            .create_texture_streaming(
                sdl3::pixels::PixelFormat::RGB24,
                super::FRAMEBUFFER_WIDTH,
                super::FRAMEBUFFER_HEIGHT,
            )
            .expect("runtime texture should be creatable");
        let frame_len = super::FRAMEBUFFER_HEIGHT as usize * super::FRAMEBUFFER_PITCH_BYTES;
        let panel_len = (super::FRAMEBUFFER_WIDTH * super::FRAMEBUFFER_HEIGHT) as usize;
        let previous_panel = vec![0_u8; panel_len];
        let current_panel = vec![3_u8; panel_len];
        let layer_sources = vec![PpuFramebufferLayerSource::Background; panel_len];
        let mut video_options = harness.runtime.video_options.clone();
        video_options.frame_blending = DesktopFrameBlendingMode::On;
        video_options.presentation_filter = true;
        harness.runtime.video_options.frame_blending = DesktopFrameBlendingMode::On;

        let mut base_state = super::FrameBlendingState::default();
        let mut first_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut first_frame,
            single_panel_render_input(&previous_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: Some(&mut base_state),
                ..super::RenderPresentationInput::default()
            },
        )
        .expect("first frame should render");
        let mut blended_base_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut blended_base_frame,
            single_panel_render_input(&current_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: Some(&mut base_state),
                ..super::RenderPresentationInput::default()
            },
        )
        .expect("blended frame should render");
        let mut raw_base_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut raw_base_frame,
            single_panel_render_input(&current_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput::default(),
        )
        .expect("raw frame should render");

        assert_ne!(
            &blended_base_frame[..3],
            &raw_base_frame[..3],
            "the base framebuffer should be blended before presentation"
        );
        assert_eq!(texture.scale_mode(), sdl3::render::ScaleMode::Linear);

        let menu_presentation = super::current_menu_presentation(
            harness.canvas.window(),
            &harness.runtime,
            &harness.machine,
            &harness.session,
        );
        harness.runtime.menu_state.open(menu_presentation);
        let open_menu_presentation = super::current_menu_presentation(
            harness.canvas.window(),
            &harness.runtime,
            &harness.machine,
            &harness.session,
        );
        let mut menu_state = super::FrameBlendingState::default();
        let mut discarded_first_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut discarded_first_frame,
            single_panel_render_input(&previous_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: Some(&mut menu_state),
                ..super::RenderPresentationInput::default()
            },
        )
        .expect("menu blend history frame should render");
        let mut blended_menu_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut blended_menu_frame,
            single_panel_render_input(&current_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: Some(&mut menu_state),
                menu_state: Some((&harness.runtime.menu_state, open_menu_presentation)),
                hud: super::RenderHudInput::default(),
            },
        )
        .expect("blended menu frame should render");
        let mut raw_menu_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut raw_menu_frame,
            single_panel_render_input(&current_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: Some((&harness.runtime.menu_state, open_menu_presentation)),
                hud: super::RenderHudInput::default(),
            },
        )
        .expect("raw menu frame should render");
        let menu_panel_pixel = 25 * super::FRAMEBUFFER_PITCH_BYTES + 25 * 3;
        assert_eq!(
            &blended_menu_frame[menu_panel_pixel..menu_panel_pixel + 3],
            &raw_menu_frame[menu_panel_pixel..menu_panel_pixel + 3],
            "opaque menu panel pixels should be drawn after the frame blend"
        );
        assert_ne!(
            &raw_menu_frame[menu_panel_pixel..menu_panel_pixel + 3],
            &raw_base_frame[menu_panel_pixel..menu_panel_pixel + 3],
            "the selected sample should be inside the menu overlay"
        );
        harness.runtime.menu_state.close();

        let hud = super::RenderHudInput {
            performance: Some(PerformanceHudSnapshot {
                fps: 60.0,
                speed_percent: 100.0,
                frame_time_ms: 16.7,
                emulation_time_ms: 10.0,
                render_time_ms: 2.0,
                pacing_time_ms: 4.0,
                audio_queue_ms: Some(12.0),
                rewind: RewindHudSnapshot::default(),
            }),
            cgb_ir: None,
            rewind_indicator: false,
            fast_forward_indicator: false,
        };
        video_options.show_performance_hud = true;
        let mut hud_state = super::FrameBlendingState::default();
        let mut discarded_hud_first_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut discarded_hud_first_frame,
            single_panel_render_input(&previous_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: Some(&mut hud_state),
                ..super::RenderPresentationInput::default()
            },
        )
        .expect("HUD blend history frame should render");
        let mut blended_hud_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut blended_hud_frame,
            single_panel_render_input(&current_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: Some(&mut hud_state),
                menu_state: None,
                hud,
            },
        )
        .expect("blended HUD frame should render");
        let mut raw_hud_frame = vec![0_u8; frame_len];
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut raw_hud_frame,
            single_panel_render_input(&current_panel, &layer_sources),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: None,
                hud,
            },
        )
        .expect("raw HUD frame should render");
        let hud_panel_pixel = 5 * super::FRAMEBUFFER_PITCH_BYTES + 5 * 3;
        assert_eq!(
            &blended_hud_frame[hud_panel_pixel..hud_panel_pixel + 3],
            &raw_hud_frame[hud_panel_pixel..hud_panel_pixel + 3],
            "opaque HUD panel pixels should be drawn after the frame blend"
        );
        assert_ne!(
            &raw_hud_frame[hud_panel_pixel..hud_panel_pixel + 3],
            &raw_base_frame[hud_panel_pixel..hud_panel_pixel + 3],
            "the selected sample should be inside the HUD overlay"
        );
    }

    #[test]
    fn render_frame_draws_corner_indicators_without_stats_hud() {
        let _guard = crate::lock_sdl_test();
        let mut harness = FrontendHarness::new("rewind-indicator-render", true, false, false);
        let texture_creator = harness.canvas.texture_creator();
        let mut texture = texture_creator
            .create_texture_streaming(
                sdl3::pixels::PixelFormat::RGB24,
                super::FRAMEBUFFER_WIDTH,
                super::FRAMEBUFFER_HEIGHT,
            )
            .expect("runtime texture should be creatable");
        let mut baseline_frame =
            vec![0_u8; super::FRAMEBUFFER_HEIGHT as usize * super::FRAMEBUFFER_PITCH_BYTES];
        let mut indicator_frame = baseline_frame.clone();
        let mut fast_forward_indicator_frame = baseline_frame.clone();
        let mut cgb_ir_helper_off_frame = baseline_frame.clone();
        let mut cgb_ir_helper_on_frame = baseline_frame.clone();
        let panel_len = (super::FRAMEBUFFER_WIDTH * super::FRAMEBUFFER_HEIGHT) as usize;
        let framebuffer = vec![0_u8; panel_len];
        let layer_sources = vec![PpuFramebufferLayerSource::Background; panel_len];
        let render_input = || super::FramebufferRenderInput {
            dimensions: super::FramebufferDimensions {
                width: super::FRAMEBUFFER_WIDTH,
                height: super::FRAMEBUFFER_HEIGHT,
            },
            panels: [
                Some(super::FramebufferPanelInput {
                    dimensions: super::FramebufferDimensions {
                        width: super::FRAMEBUFFER_WIDTH,
                        height: super::FRAMEBUFFER_HEIGHT,
                    },
                    framebuffer: &framebuffer,
                    framebuffer_layer_sources: &layer_sources,
                    bgwin_framebuffer: &framebuffer,
                    backdrop_framebuffer: &framebuffer,
                    bgwin_framebuffer_layer_sources: &layer_sources,
                    display_palette: super::DMG_DISPLAY_PALETTE,
                    cgb_framebuffer_rgb555: None,
                    sgb_framebuffer_rgb555: None,
                }),
                None,
                None,
                None,
            ],
        };
        let mut video_options = harness.runtime.video_options.clone();
        video_options.show_performance_hud = false;

        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut baseline_frame,
            render_input(),
            &video_options,
            super::RenderPresentationInput::default(),
        )
        .expect("baseline frame should render");
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut indicator_frame,
            render_input(),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: None,
                hud: super::RenderHudInput {
                    performance: None,
                    cgb_ir: None,
                    rewind_indicator: true,
                    fast_forward_indicator: false,
                },
            },
        )
        .expect("rewind indicator frame should render");

        assert_ne!(
            indicator_frame, baseline_frame,
            "rewind indicator should render independently from the stats HUD"
        );

        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut fast_forward_indicator_frame,
            render_input(),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: None,
                hud: super::RenderHudInput {
                    performance: None,
                    cgb_ir: None,
                    rewind_indicator: false,
                    fast_forward_indicator: true,
                },
            },
        )
        .expect("fast-forward indicator frame should render");
        assert_ne!(
            fast_forward_indicator_frame, baseline_frame,
            "fast-forward indicator should render independently from the stats HUD"
        );

        let cgb_ir_snapshot = super::CgbInfraredHudSnapshot {
            p1: super::CgbInfraredParticipantHudSnapshot {
                read_enabled: true,
                sensor_warmed: true,
                ..super::CgbInfraredParticipantHudSnapshot::default()
            },
            p2: super::CgbInfraredParticipantHudSnapshot {
                read_enabled: true,
                sensor_warmed: true,
                ..super::CgbInfraredParticipantHudSnapshot::default()
            },
        };
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut cgb_ir_helper_off_frame,
            render_input(),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: None,
                hud: super::RenderHudInput {
                    performance: None,
                    cgb_ir: Some(cgb_ir_snapshot),
                    rewind_indicator: false,
                    fast_forward_indicator: false,
                },
            },
        )
        .expect("CGB IR helper-off frame should render");
        assert_eq!(
            cgb_ir_helper_off_frame, baseline_frame,
            "CGB IR helper should not render while the video option is disabled"
        );

        video_options.show_cgb_infrared_helper = true;
        super::render_frame(
            &mut harness.canvas,
            &mut texture,
            &mut cgb_ir_helper_on_frame,
            render_input(),
            &video_options,
            super::RenderPresentationInput {
                frame_blending_state: None,
                menu_state: None,
                hud: super::RenderHudInput {
                    performance: None,
                    cgb_ir: Some(cgb_ir_snapshot),
                    rewind_indicator: false,
                    fast_forward_indicator: false,
                },
            },
        )
        .expect("CGB IR helper-on frame should render");
        assert_ne!(
            cgb_ir_helper_on_frame, baseline_frame,
            "CGB IR helper should render when the video option is enabled"
        );
    }

    #[test]
    fn linked_runtime_routes_p1_and_p2_keyboard_input_independently() {
        let _guard = crate::lock_sdl_test();
        let mut harness = FrontendHarness::new("linked-keyboard-routing", true, false, false);
        let secondary_machine = Machine::new_summary(
            MachineConfig::new(ConsoleModel::GameBoy).with_startup_mode(StartupMode::SkipBoot),
        );
        harness
            .machine
            .attach_secondary_dmg04(secondary_machine)
            .expect("secondary machine should attach");

        harness.push_key(Keycode::Up, true);
        harness.push_key_with_scancode(Keycode::W, Scancode::W, true);
        harness
            .process_events()
            .expect("linked keyboard press should process");
        harness.machine.step_t_cycle();

        assert_eq!(
            harness
                .machine
                .machine_for_player_slot(super::PlayerSlot::P1)
                .expect("P1 should map to the linked runtime machine")
                .joypad()
                .snapshot()
                .pressed_mask,
            0x04
        );
        assert_eq!(
            harness
                .machine
                .machine_for_player_slot(super::PlayerSlot::P2)
                .expect("P2 should map to the linked runtime secondary machine")
                .joypad()
                .snapshot()
                .pressed_mask,
            0x04
        );

        harness.push_key(Keycode::Up, false);
        harness.push_key_with_scancode(Keycode::W, Scancode::W, false);
        harness
            .process_events()
            .expect("linked keyboard release should process");
        harness.machine.step_t_cycle();

        assert_eq!(
            harness
                .machine
                .machine_for_player_slot(super::PlayerSlot::P1)
                .expect("P1 should map to the linked runtime machine")
                .joypad()
                .snapshot()
                .pressed_mask,
            0
        );
        assert_eq!(
            harness
                .machine
                .machine_for_player_slot(super::PlayerSlot::P2)
                .expect("P2 should map to the linked runtime secondary machine")
                .joypad()
                .snapshot()
                .pressed_mask,
            0
        );
    }

    #[test]
    fn sgb_single_runtime_routes_multiplayer_keyboard_slots_to_host_controllers() {
        let _guard = crate::lock_sdl_test();
        let mut harness = FrontendHarness::new("sgb-keyboard-routing", true, false, false);
        harness.machine = super::DesktopEmulationSession::new_single(Machine::new_summary(
            MachineConfig::new(ConsoleModel::GameBoy)
                .with_startup_mode(StartupMode::SkipBoot)
                .with_sgb_profile(SgbHostProfile::SgbNtsc),
        ));

        harness.push_key_with_scancode(Keycode::E, Scancode::E, true);
        harness.push_key_with_scancode(Keycode::B, Scancode::B, true);
        harness.push_key_with_scancode(Keycode::M, Scancode::M, true);
        harness
            .process_events()
            .expect("SGB keyboard press should process");
        harness.machine.step_t_cycle();

        assert_eq!(
            harness
                .machine
                .primary_machine()
                .sgb_host()
                .snapshot()
                .multiplayer
                .player_pressed_masks,
            [0x00, 0x80, 0x10, 0x20],
            "P2 START, P3 A, and P4 B should route into SGB host controller slots instead of Game Link machines"
        );
        assert_eq!(
            harness
                .machine
                .primary_machine()
                .joypad()
                .snapshot()
                .pressed_mask,
            0,
            "SGB P2/P3/P4 desktop keys must not leak into the local P1 joypad"
        );

        harness.push_key_with_scancode(Keycode::E, Scancode::E, false);
        harness.push_key_with_scancode(Keycode::B, Scancode::B, false);
        harness.push_key_with_scancode(Keycode::M, Scancode::M, false);
        harness
            .process_events()
            .expect("SGB keyboard release should process");
        harness.machine.step_t_cycle();

        assert_eq!(
            harness
                .machine
                .primary_machine()
                .sgb_host()
                .snapshot()
                .multiplayer
                .player_pressed_masks,
            [0x00; 4]
        );
    }

